B.amv={"\u0623\u0647\u0644\u0627\u064b \u0628\u064a\u0643 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 \u0645\u062f\u0642\u0642 \ud83d\udc4b":0,"\u0627\u0644\u0641\u0631\u0639 \u0648\u0627\u0633\u0645\u0643 \ud83c\udfea":1,"\u0634\u0643\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \ud83c\udfa8":2,"\u0642\u0633\u0645 \u0627\u0644\u062c\u0631\u062f \ud83d\udce6":3,"\u0642\u0633\u0645 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0641\u0646\u064a \ud83c\udfa7":4,"\u0642\u0633\u0645 \u0627\u0644\u0645\u0634\u062a\u0631\u064a\u0627\u062a \ud83e\uddfe":5,"\u0642\u0633\u0645 \u0627\u0633\u062a\u0644\u0627\u0645 \u0641\u0648\u0627\u062a\u064a\u0631 \ud83d\udce5":6,"\u0627\u0644\u062c\u0631\u062f \u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064a \ud83c\udfb2":7,"\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u062a \ud83e\uddf0":8,"\u062a\u062d\u062f\u064a\u062b \u0645\u0646 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \ud83d\udd04":9,"\u0627\u0633\u062a\u0639\u0644\u0627\u0645 \u0635\u0646\u0641 \ud83d\udd0e":10,"\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2699\ufe0f":11,"\u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \ud83d\udd14|\u0645\u0647\u0645 \u062c\u062f\u0627\u064b \u062a\u0634\u063a\u0651\u0644\u0647\u0627":12,"\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \ud83d\udce4":13,"\u0645\u0648\u0642\u0639 \u0645\u062f\u0642\u0642 \ud83c\udf10":14,"\u0627\u0644\u0634\u0643\u0644 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \ud83c\udfa8":15,"\u0627\u0644\u0634\u0631\u0648\u062d\u0627\u062a \ud83c\udfac":16,"\u0634\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \ud83d\udcac|\u062a\u0643\u0644\u0651\u0645 \u0641\u0631\u064a\u0642 \u0645\u062f\u0642\u0642":17,"\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2b06\ufe0f":18,"\u062e\u0644\u0627\u0635 \u0643\u062f\u0647 \ud83c\udf89":19,"\u0634\u0627\u0634\u0629 \u0627\u0644\u0635\u0646\u0641 \ud83d\udce6":20,"\u0627\u0633\u0645 \u0627\u0644\u0635\u0646\u0641":21,"\u0635\u0648\u0631\u0629 \u0627\u0644\u0635\u0646\u0641 \ud83d\uddbc\ufe0f":22,"\u0627\u0646\u0637\u0642 \u0627\u0644\u0627\u0633\u0645 \ud83d\udd0a":23,"\u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0627\u0644\u0635\u0646\u0641 \u26a0\ufe0f":24,"\u0627\u0644\u0645\u0646\u0637\u0642\u0629 \ud83d\udccd":25,"\u0627\u0644\u0643\u0631\u0627\u062a\u064a\u0646 \ud83d\udce6":26,"\u0641\u0631\u0642 \u0627\u0644\u062c\u0631\u062f":27,"\u0627\u0644\u0643\u0645\u064a\u0629 \u0642\u0628\u0644 \u0648\u0628\u0639\u062f":28,"\u0639\u062f\u062f \u0627\u0644\u0642\u0637\u0639 \u270d\ufe0f":29,"\u062a\u0639\u062f\u064a\u0644 \u062e\u0627\u0646\u0629 \u0642\u062f\u064a\u0645\u0629 \ud83d\udd13":30,"\u0627\u0644\u062d\u0641\u0638 \u2b07\ufe0f":31,"\u0648\u0632\u0646 \u0627\u0644\u0645\u064a\u0632\u0627\u0646 \u2696\ufe0f":32,"\u0641\u0627\u062a\u0648\u0631\u0629 \u062c\u062f\u064a\u062f\u0629 \ud83e\uddfe":33,"\u0627\u0644\u0641\u0631\u0639 \ud83c\udfea":34,"\u0633\u062c\u0644 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \ud83d\udcc2":35,"\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0641\u0646\u064a \ud83d\udee0\ufe0f":36,"\u0634\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \ud83d\udcac|\u062a\u0643\u0644\u0651\u0645 \u0627\u0644\u062f\u0639\u0645 \u0641\u064a":37,"\u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \ud83d\udd14|\u0643\u0644 \u0623\u062e\u0628\u0627\u0631 \u0641\u0648\u0627\u062a\u064a":38,"\u062f\u0644\u064a\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \ud83d\udcd6":39,"\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u2630|\u0641\u064a\u0647\u0627 \u0635\u0648\u0631\u062a\u0643 \u0627\u0644\u0634\u062e\u0635":40,"\u0635\u0648\u0651\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \ud83d\udcf8":41,"\u0627\u0644\u0645\u0648\u0631\u062f \ud83d\ude9a":42,"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \ud83d\udcb0":43,"\u0633\u0643\u0627\u0646 \u0627\u0644\u0635\u0646\u0641 \ud83d\udcf7":44,"\u0628\u0627\u0644\u0627\u0633\u0645 \ud83d\udd0e":45,"\u0631\u0627\u062c\u0639 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \ud83d\udc40":46,"\u0643\u0644\u0651\u0645 \u0627\u0644\u062f\u0639\u0645 \u0639\u0646 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \ud83d\udcac":47,"\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \ud83d\udcca":48,"\u0627\u0633\u062a\u0639\u062c\u0627\u0644 \u0627\u0644\u0625\u062f\u062e\u0627\u0644 \ud83d\udd25":49,"\u0627\u0628\u0639\u062a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u2705":50,"\u0645\u064a\u0646 \u0627\u0644\u0644\u064a \u0647\u064a\u0634\u062a\u063a\u0644\u061f \ud83d\udc65":51,"\u0627\u0633\u0645\u0643":52,"\u0634\u064a\u0644 \u0627\u0644\u0627\u0633\u0645 \u0645\u0646 \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644":53,"\u062f\u062e\u0648\u0644 \u0645\u0648\u0638\u0641 \u062a\u0627\u0646\u064a \u2795":54,"\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \ud83d\udd12":55,"\u0623\u0648\u0644 \u062f\u062e\u0648\u0644 \ud83d\udc4b":56,"\u0627\u0633\u0645\u0643 \u0623\u0648 \u0631\u0642\u0645 \u0645\u0648\u0628\u0627\u064a\u0644\u0643":57,"\u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0633\u0631\u064a \ud83d\udd11":58,"\u0645\u062d\u062a\u0627\u062c \u0646\u062a \u0623\u0648\u0644 \u0645\u0631\u0629 \u0628\u0633 \ud83d\udcf6":59,"\u062f\u062e\u0648\u0644":60,"\u0623\u0647\u0644\u0627\u064b \u0628\u064a\u0643 \u0641\u064a \u0634\u0627\u0634\u0629 \u0627\u0644\u062c\u0631\u062f \ud83d\udc4b":61,"\u0627\u0633\u0645 \u0627\u0644\u0641\u0631\u0639 \ud83c\udfea":62,"\u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0644\u064a \u0628\u062a\u062c\u0631\u062f \u0641\u064a\u0647\u0627 \ud83d\udccd":63,"\u0632\u0631\u0627\u0631 \xab\u062e\u0644\u0635\u062a\xbb \u2705":64,"\u062d\u0627\u0644\u0629 \u0627\u0644\u0646\u062a \ud83d\udcf6":65,"\u0627\u0644\u0631\u0641\u0639 \u0644\u0644\u0634\u064a\u062a \u2601\ufe0f":66,"\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0623\u0635\u0646\u0627\u0641 \ud83d\udd04":67,"\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u2630|\u0645\u0646 \u0647\u0646\u0627 \u0628\u062a\u0648\u0635\u0644 \u0644\u0643\u0644":68,"\u0637\u0644\u0628 \u0627\u0644\u062c\u0631\u062f \ud83d\udccb":69,"\u0623\u0635\u0646\u0627\u0641 \u0645\u0627 \u0627\u062a\u062d\u0641\u0638\u062a\u0634 \u26a0\ufe0f":70,"\u0646\u0633\u0628\u0629 \u0627\u0644\u062c\u0631\u062f \ud83d\udcca":71,"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \ud83d\udca1":72,"\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0635\u0646\u0627\u0641 \u0627\u0644\u0644\u064a \u0628\u062a\u062a\u0631\u0641\u0639 \u23f3":73,"\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u0641\u0648\u0642 \ud83d\udfe7":74,"\u0627\u0644\u0634\u0627\u0634\u0629 \u0645\u0634 \u0647\u062a\u0646\u0637\u0641\u064a \ud83d\udd06":75,"\u0627\u0643\u062a\u0628 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \u2328\ufe0f":76,"\u062f\u0648\u0651\u0631 \u0628\u0627\u0644\u0627\u0633\u0645 \ud83d\udd0e":77,"\u0632\u0631\u0627\u0631 \u0627\u0644\u0645\u0633\u062d \u0627\u0644\u0643\u0628\u064a\u0631 \ud83d\udcf7":78,"\u0644\u0645\u0627 \u062a\u062e\u0644\u0635 \ud83c\udfc1":79,"\u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \ud83d\udce5":80,"\u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0627\u0644\u0644\u064a \u062c\u0627\u064a\u0629 \ud83d\udccb":81,"\u0641\u0627\u062a\u0648\u0631\u0629 \u0645\u0646 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \ud83d\udce5":82,"\u0631\u0641\u0639 \u0645\u0644\u0641 \u0627\u0633\u062a\u0644\u0627\u0645 \ud83d\udce4":83,"\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u22ee":84,"\u0634\u0627\u0634\u0629 \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \ud83d\udce6":85,"\u0627\u0644\u062a\u0627\u0628\u0627\u062a \ud83d\uddc2\ufe0f":86,"\u0627\u0644\u0639\u062f\u0627\u062f \ud83d\udcca":87,"\u062f\u0648\u0651\u0631 \u0623\u0648 \u0627\u0643\u062a\u0628 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \ud83d\udd0e":88,"\u0627\u0639\u0645\u0644 \u0633\u0643\u0627\u0646 \ud83d\udcf7":89,"\u062e\u0644\u0635\u062a \u2705":90,"\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \ud83d\udce4":91,"\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2699\ufe0f|\u062d\u062c\u0645 \u0627\u0644\u0639\u0631\u0636":92,"\u0645\u0641\u064a\u0634 \u0646\u062a\u061f \u2601\ufe0f":93,"\u0623\u0647\u0644\u0627\u064b \u0628\u064a\u0643 \u0641\u064a \u062c\u0631\u062f \u0645\u062f\u0642\u0642 \ud83d\udc4b":94,"\u0627\u0645\u0633\u062d \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \ud83d\udcf7":95,"\u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644 \u0628\u064a\u0646\u0628\u0647\u0643 \ud83d\udd0a":96,"\u0627\u0643\u062a\u0628 \u0627\u0644\u0639\u062f\u062f \u0648\u062f\u0648\u0633 Enter \u270d\ufe0f":97,"\u0644\u0648\u062d\u0629 \u0623\u0631\u0642\u0627\u0645 \u0643\u0628\u064a\u0631\u0629 \ud83d\udd22":98,"\u0646\u0641\u0633 \u0627\u0644\u0635\u0646\u0641 \u0641\u064a \u0623\u0643\u062a\u0631 \u0645\u0646 \u0645\u0643\u0627\u0646 \ud83d\udd01":99,"\u0635\u0648\u0631\u0629 \u0644\u0643\u0644 \u0645\u0646\u0637\u0642\u0629 \ud83d\udcf8":100,"\u0645\u0641\u064a\u0634 \u0646\u062a\u061f \u0648\u0644\u0627 \u064a\u0647\u0645\u0643 \u2601\ufe0f":101,"\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u2630|\u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u062a\u0634\u0648\u0641":102}
B.r7=new A.ak(B.amv,["\u0623\u064e\u0647\u0652\u0644\u064b\u0627 \u0628\u0650\u064a\u0643 \u0641\u064a \u062a\u064e\u0637\u0652\u0628\u064a\u0642 \u0645\u064f\u062f\u064e\u0642\u0650\u0651\u0642. \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u062f\u064e\u0647 \u0641\u0650\u064a\u0647 \u0643\u064f\u0644\u0651 \u0634\u064f\u063a\u0652\u0644\u064e\u0643 \u0641\u064a \u0645\u064e\u0643\u0627\u0646 \u0648\u0627\u062d\u0650\u062f: \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0648\u0627\u0644\u0645\u064f\u0634\u0652\u062a\u064e\u0631\u064e\u064a\u0627\u062a\u060c \u0648\u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0627\u0644\u0641\u064e\u0646\u0650\u0651\u064a\u060c \u0648\u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645 \u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631. \u0647\u064e\u0646\u0652\u0639\u064e\u062f\u0650\u0651\u064a \u0639\u064e\u0644\u0649 \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u064a \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u062f\u064a \u0648\u0627\u062d\u0652\u062f\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629. \u062f\u064f\u0648\u0633 \u0627\u0644\u062a\u064e\u0651\u0627\u0644\u064a\u060c \u0623\u064e\u0648\u0652 \u062f\u064f\u0648\u0633 \u0641\u064a \u0623\u064e\u064a\u0651 \u062d\u0650\u062a\u064e\u0651\u0629.","\u0647\u0650\u0646\u0627 \u0627\u0633\u0652\u0645 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0644\u064a \u0625\u0650\u0646\u0652\u062a\u064e \u0634\u064e\u063a\u0651\u0627\u0644 \u0639\u064e\u0644\u0650\u064a\u0647\u060c \u0648\u062a\u064e\u062d\u0652\u062a\u064f\u0647 \u0627\u0633\u0652\u0645\u064e\u0643. \u0644\u064e\u0648\u0652 \u0644\u0650\u064a\u0643 \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u0641\u064e\u0631\u0652\u0639\u060c \u0647\u064e\u062a\u0652\u0644\u0627\u0642\u064a \u0633\u064e\u0647\u0652\u0645 \u062c\u064e\u0646\u0652\u0628 \u0627\u0644\u0627\u0633\u0652\u0645\u060c \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647 \u0648\u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0641\u064e\u0631\u0652\u0639. \u0643\u064f\u0644\u0651 \u0627\u0644\u0644\u064a \u0647\u064e\u062a\u0650\u0639\u0652\u0645\u0650\u0644\u064f\u0647 \u0628\u064e\u0639\u0652\u062f \u0643\u0650\u062f\u064e\u0647\u060c \u0628\u0650\u064a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u062f\u064e\u0647.","\u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u062a\u0650\u062e\u0652\u062a\u0627\u0631 \u0634\u064e\u0643\u0652\u0644 \u0648\u0623\u064e\u0644\u0652\u0648\u0627\u0646 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0627\u0644\u0644\u064a \u064a\u0650\u0631\u064e\u064a\u064e\u0651\u062d \u0639\u0650\u064a\u0646\u064e\u0643\u060c \u0641\u0627\u062a\u0650\u062d \u0623\u064e\u0648\u0652 \u063a\u0627\u0645\u0650\u0642. \u062f\u064e\u0647 \u0634\u064e\u0643\u0652\u0644 \u0628\u064e\u0633\u0651\u060c \u0648\u0645\u064e\u0628\u0650\u064a\u0652\u063a\u064e\u064a\u064e\u0651\u0631\u0652\u0634 \u0623\u064e\u064a\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u064a \u0627\u0644\u0634\u064f\u0651\u063a\u0652\u0644.","\u0642\u0650\u0633\u0652\u0645 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0644\u0650\u0639\u064e\u062f\u0651 \u0627\u0644\u0628\u0650\u0636\u0627\u0639\u064e\u0629 \u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u0631\u064f\u0651\u0641\u0648\u0641 \u0648\u0627\u0644\u0645\u064e\u062e\u0652\u0632\u064e\u0646. \u062c\u064f\u0648\u0651\u0627\u0647 \u0628\u0650\u062a\u0650\u0645\u0652\u0633\u064e\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0643\u064f\u0644\u0651 \u0635\u0650\u0646\u0652\u0641 \u0628\u0650\u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0648\u062a\u0650\u0643\u0652\u062a\u0650\u0628 \u0639\u064e\u062f\u064e\u062f\u064f\u0647\u060c \u0648\u0627\u0644\u062c\u064e\u0631\u0652\u062f \u0628\u0650\u064a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638 \u0648\u064a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647. \u0648\u062c\u064f\u0648\u0651\u0647 \u0627\u0644\u0642\u0650\u0633\u0652\u0645 \u0641\u0650\u064a\u0647 \u0634\u064e\u0631\u0652\u062d \u062e\u0627\u0635\u0651 \u0628\u0650\u064a\u0647 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u062a\u0650\u0641\u0652\u062a\u064e\u062d\u064f\u0647.","\u0642\u0650\u0633\u0652\u0645 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0627\u0644\u0641\u064e\u0646\u0650\u0651\u064a. \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0645\u064f\u0634\u0652\u0643\u0650\u0644\u064e\u0629 \u0641\u064a \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645 \u0623\u064e\u0648\u0652 \u0627\u0644\u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c\u060c \u0632\u064e\u064a\u0651 \u0633\u0650\u0639\u0652\u0631 \u063a\u064e\u0644\u064e\u0637\u060c \u0623\u064e\u0648\u0652 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0634 \u0638\u0627\u0647\u0650\u0631\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0637\u064e\u0651\u0627\u0628\u0652\u0639\u064e\u0629\u060c \u0627\u0641\u0652\u062a\u064e\u062d \u0637\u064e\u0644\u064e\u0628 \u062f\u064e\u0639\u0652\u0645 \u0648\u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u064f\u0634\u0652\u0643\u0650\u0644\u064e\u0629. \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0628\u0650\u064a\u0652\u0631\u064f\u062f\u0651 \u0639\u064e\u0644\u0650\u064a\u0643 \u0648\u064a\u0650\u062d\u0650\u0644\u0651\u0647\u0627\u060c \u0648\u062a\u0650\u062a\u0627\u0628\u0650\u0639 \u0627\u0644\u0637\u064e\u0651\u0644\u064e\u0628 \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u064a\u0650\u062a\u0652\u0642\u0650\u0641\u0650\u0644. \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0623\u064e\u062d\u0652\u0645\u064e\u0631 \u0639\u064e\u0644\u0649 \u0627\u0644\u0642\u0650\u0633\u0652\u0645\u060c \u0647\u064f\u0648\u064e\u0651 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0637\u064e\u0651\u0644\u064e\u0628\u0627\u062a \u0627\u0644\u0645\u064e\u0641\u0652\u062a\u0648\u062d\u064e\u0629.","\u0642\u0650\u0633\u0652\u0645 \u0627\u0644\u0645\u064f\u0634\u0652\u062a\u064e\u0631\u064e\u064a\u0627\u062a. \u0644\u064e\u0645\u0651\u0627 \u0628\u0650\u0636\u0627\u0639\u064e\u0629 \u062a\u064f\u0648\u0635\u064e\u0644 \u0645\u0650\u0646 \u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f\u060c \u0635\u064e\u0648\u064e\u0651\u0631 \u0641\u0627\u062a\u0648\u0631\u0650\u0629 \u0627\u0644\u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f\u060c \u0648\u0633\u064e\u062c\u0650\u0651\u0644 \u0623\u064e\u0635\u0652\u0646\u0627\u0641\u0652\u0647\u0627\u060c \u0648\u0627\u0628\u0652\u0639\u064e\u062a\u0652\u0647\u0627 \u0644\u0650\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u064a\u0650\u062f\u064e\u062e\u064e\u0651\u0644\u0652\u0647\u0627 \u0639\u064e\u0644\u0649 \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645. \u0648\u0628\u064e\u0639\u0652\u062f \u0645\u0627 \u062a\u0650\u062f\u0652\u062e\u064f\u0644\u060c \u0628\u0650\u064a\u064f\u0648\u0635\u064e\u0644\u064e\u0643 \u0625\u0650\u0634\u0652\u0639\u0627\u0631\u060c \u0648\u062a\u0652\u0631\u0627\u062c\u0650\u0639 \u0635\u0648\u0631\u0650\u0629 \u0627\u0644\u0625\u0650\u062b\u0652\u0628\u0627\u062a. \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0623\u064e\u062d\u0652\u0645\u064e\u0631 \u0639\u064e\u0644\u0649 \u0627\u0644\u0642\u0650\u0633\u0652\u0645\u060c \u0647\u064f\u0648\u064e\u0651 \u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631 \u0627\u0644\u0644\u064a \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0631\u064e\u062c\u064e\u0651\u0639\u0652\u0647\u0627\u060c \u0648\u0645\u0650\u062d\u0652\u062a\u0627\u062c\u064e\u0629 \u062a\u064e\u0639\u0652\u062f\u064a\u0644.","\u0642\u0650\u0633\u0652\u0645 \u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645 \u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631\u060c \u0644\u0650\u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645 \u0627\u0644\u0628\u0650\u0636\u0627\u0639\u064e\u0629 \u0627\u0644\u0644\u064a \u062c\u0627\u064a\u064e\u0651\u0629 \u0645\u0650\u0646 \u0627\u0644\u0645\u064e\u062e\u0652\u0632\u064e\u0646 \u0627\u0644\u0631\u064e\u0651\u0626\u064a\u0633\u064a. \u062a\u0650\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629\u060c \u0648\u062a\u0650\u0639\u0650\u062f\u0651 \u0627\u0644\u0644\u064a \u0648\u0650\u0635\u0650\u0644 \u0635\u0650\u0646\u0652\u0641 \u0635\u0650\u0646\u0652\u0641\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u064a\u0650\u0637\u064e\u0644\u064e\u0651\u0639\u0652\u0644\u064e\u0643 \u0627\u0644\u0646\u064e\u0651\u0627\u0642\u0650\u0635 \u0648\u0627\u0644\u0632\u0650\u0651\u064a\u0627\u062f\u064e\u0629.","\u0627\u0644\u062c\u064e\u0631\u0652\u062f \u0627\u0644\u0639\u064e\u0634\u0652\u0648\u0627\u0626\u064a. \u062c\u064e\u0631\u0652\u062f \u0633\u064e\u0631\u064a\u0639 \u0644\u0650\u0639\u064e\u062f\u064e\u062f \u0635\u064f\u063a\u064e\u064a\u064e\u0651\u0631 \u0645\u0650\u0646 \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u0628\u0650\u064a\u0650\u062e\u0652\u062a\u0627\u0631\u0652\u0647\u0627 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u0627\u0644\u0645\u064f\u062f\u064a\u0631 \u064a\u0650\u0639\u0652\u0631\u064e\u0641 \u0627\u0644\u0641\u064f\u0631\u0648\u0642\u0627\u062a \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u062c\u064e\u0631\u0652\u062f \u0643\u0627\u0645\u0650\u0644.","\u062a\u064e\u062d\u0652\u062a \u0627\u0644\u0623\u064e\u0642\u0652\u0633\u0627\u0645\u060c \u0641\u0650\u064a\u0647 \u0623\u064e\u062f\u064e\u0648\u0627\u062a \u0645\u064f\u0647\u0650\u0645\u064e\u0651\u0629. \u0647\u064e\u0646\u0652\u0639\u064e\u062f\u0650\u0651\u064a \u0639\u064e\u0644\u0650\u064a\u0647\u0627 \u0648\u0627\u062d\u0652\u062f\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629.","\u062a\u064e\u062d\u0652\u062f\u064a\u062b \u0645\u0650\u0646 \u0627\u0644\u0631\u064e\u0651\u0626\u064a\u0633\u064a. \u062f\u064e\u0647 \u0644\u0650\u0644\u0645\u064f\u062f\u064a\u0631: \u0628\u0650\u064a\u0652\u062c\u064a\u0628 \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u062c\u0650\u062f\u064a\u062f\u064e\u0629\u060c \u0648\u0627\u0644\u0623\u064e\u0633\u0652\u0639\u0627\u0631\u060c \u0648\u0627\u0644\u0648\u064e\u062d\u064e\u062f\u0627\u062a\u060c \u0645\u0650\u0646 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0631\u064e\u0651\u0626\u064a\u0633\u064a \u0644\u0650\u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c \u0627\u0644\u0641\u064e\u0631\u0652\u0639.","\u0627\u0633\u0652\u062a\u0650\u0639\u0652\u0644\u0627\u0645 \u0635\u0650\u0646\u0652\u0641. \u0627\u0645\u0652\u0633\u064e\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0623\u064e\u064a\u0651 \u0635\u0650\u0646\u0652\u0641\u060c \u062a\u0650\u0639\u0652\u0631\u064e\u0641 \u0633\u0650\u0639\u0652\u0631 \u0634\u0650\u0631\u0627\u0647\u060c \u0648\u0633\u0650\u0639\u0652\u0631 \u0628\u0650\u064a\u0639\u064f\u0647\u060c \u0648\u0643\u0650\u0645\u0650\u0651\u064a\u062a\u064f\u0647\u060c \u0648\u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f\u064f\u0647\u060c \u0645\u0650\u0646 \u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c \u0627\u0644\u0628\u0650\u064a\u0639\u060c \u0648\u0645\u064e\u0639\u0627\u0647 \u0635\u0648\u0631\u0652\u062a\u064f\u0647.","\u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a. \u0641\u0650\u064a\u0647\u0627: \u062a\u064e\u063a\u0652\u064a\u064a\u0631 \u0627\u0644\u0641\u064e\u0631\u0652\u0639\u060c \u0648\u0635\u0648\u0631\u0652\u062a\u064e\u0643\u060c \u0648\u062d\u0650\u0633\u0627\u0628\u064e\u0643 \u0648\u0643\u0650\u0644\u0652\u0645\u0650\u0629 \u0627\u0644\u0633\u0650\u0651\u0631\u0651\u060c \u0648\u0645\u064f\u0648\u064e\u0638\u064e\u0651\u0641\u064a\u0646 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0648\u0635\u064e\u0644\u0627\u062d\u0650\u064a\u0651\u0627\u062a\u0652\u0647\u064f\u0645 \u0644\u0650\u0644\u0645\u064f\u062f\u064a\u0631\u060c \u0648\u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u0627\u0644\u062e\u064f\u0631\u0648\u062c. \u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u0627\u0644\u062e\u064f\u0631\u0648\u062c \u0628\u0650\u064a\u0652\u0631\u064e\u062c\u064e\u0651\u0639\u064e\u0643 \u0644\u0650\u0642\u0627\u064a\u0652\u0645\u0650\u0629 \u0627\u0644\u0623\u064e\u0633\u0627\u0645\u064a \u0628\u064e\u0633\u0651\u060c \u0648\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u062a\u0627\u0646\u064a \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0646\u0650\u062a\u0651.","\u0627\u0644\u0625\u0650\u0634\u0652\u0639\u0627\u0631\u0627\u062a. \u0645\u064f\u0647\u0650\u0645\u0651 \u062c\u0650\u062f\u064b\u0651\u0627 \u062a\u0650\u0634\u064e\u063a\u064e\u0651\u0644\u0652\u0647\u0627\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u064a\u064f\u0648\u0635\u064e\u0644\u064e\u0643 \u0644\u064e\u0645\u0651\u0627 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u064a\u0650\u0631\u064f\u062f\u0651 \u0639\u064e\u0644\u0650\u064a\u0643\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645\u060c \u0623\u064e\u0648\u0652 \u062a\u0650\u0631\u0652\u062c\u064e\u0639. \u0644\u064e\u0648\u0652 \u0645\u064e\u0643\u0652\u062a\u0648\u0628 \u062a\u064e\u0641\u0652\u0639\u064a\u0644 \u0627\u0644\u0625\u0650\u0634\u0652\u0639\u0627\u0631\u0627\u062a\u060c \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647\u0627\u060c \u0648\u0648\u0627\u0641\u0650\u0642 \u0639\u064e\u0644\u0649 \u0627\u0644\u0625\u0650\u0630\u0652\u0646 \u0627\u0644\u0644\u064a \u0647\u064e\u064a\u0650\u0638\u0652\u0647\u064e\u0631.","\u0645\u064f\u0634\u0627\u0631\u0652\u0643\u0650\u0629 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642. \u062a\u0650\u0628\u0652\u0639\u064e\u062a \u0644\u064a\u0646\u0652\u0643 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0644\u0650\u0632\u064e\u0645\u064a\u0644\u064e\u0643\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u064a\u0650\u0646\u064e\u0632\u0650\u0651\u0644\u064f\u0647 \u0639\u064e\u0644\u0649 \u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u064f\u0647.","\u0645\u064e\u0648\u0652\u0642\u0650\u0639 \u0645\u064f\u062f\u064e\u0642\u0650\u0651\u0642. \u0628\u0650\u064a\u0650\u0641\u0652\u062a\u064e\u062d \u0645\u064e\u0648\u0652\u0642\u0650\u0639 \u0634\u0650\u0631\u0652\u0643\u0650\u0629 \u0645\u064f\u062f\u064e\u0642\u0650\u0651\u0642.","\u0627\u0644\u0634\u064e\u0651\u0643\u0652\u0644 \u0648\u0627\u0644\u0623\u064e\u0644\u0652\u0648\u0627\u0646. \u0646\u064e\u0641\u0652\u0633 \u0632\u064f\u0631\u0627\u0631 \u0627\u0644\u0634\u064e\u0651\u0643\u0652\u0644 \u0627\u0644\u0644\u064a \u0641\u064f\u0648\u0642: \u062a\u0650\u062e\u0652\u062a\u0627\u0631 \u0634\u064e\u0643\u0652\u0644 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642.","\u0627\u0644\u0634\u064f\u0651\u0631\u0648\u062d\u0627\u062a. \u0641\u064a\u062f\u064a\u0648 \u0628\u0650\u064a\u0650\u0634\u0652\u0631\u064e\u062d \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u062e\u064f\u0637\u0652\u0648\u064e\u0629 \u0628\u0650\u062e\u064f\u0637\u0652\u0648\u064e\u0629. \u0644\u064e\u0648\u0652 \u062d\u0627\u062c\u064e\u0629 \u0645\u0650\u0634 \u0648\u0627\u0636\u0652\u062d\u064e\u0629\u060c \u0634\u064f\u0648\u0641\u064f\u0647.","\u0634\u0627\u062a \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645. \u0643\u064e\u0644\u0650\u0651\u0645 \u0641\u064e\u0631\u064a\u0642 \u0645\u064f\u062f\u064e\u0642\u0650\u0651\u0642 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644 \u0641\u064a \u0623\u064e\u064a\u0651 \u062d\u0627\u062c\u064e\u0629. \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0650\u064a\u0647\u060c \u0647\u064f\u0648\u064e\u0651 \u0627\u0644\u0631\u064e\u0651\u0633\u0627\u064a\u0650\u0644 \u0627\u0644\u062c\u0650\u062f\u064a\u062f\u064e\u0629 \u0627\u0644\u0644\u064a \u0645\u0627 \u0642\u064e\u0631\u0650\u064a\u062a\u0652\u0647\u0627\u0634.","\u062a\u064e\u062d\u0652\u062f\u064a\u062b \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642. \u0644\u064e\u0648\u0652 \u0642\u0627\u0644\u0648\u0644\u064e\u0643 \u0641\u0650\u064a\u0647 \u0646\u064f\u0633\u0652\u062e\u064e\u0629 \u062c\u0650\u062f\u064a\u062f\u064e\u0629\u060c \u0623\u064e\u0648\u0652 \u062d\u0627\u062c\u064e\u0629 \u0645\u0650\u0634 \u0634\u064e\u063a\u0651\u0627\u0644\u064e\u0629 \u0632\u064e\u064a\u0651 \u0645\u0627 \u0627\u0644\u0645\u064e\u0641\u0652\u0631\u0648\u0636\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u064a\u0650\u062c\u064a\u0628 \u0623\u064e\u062d\u0652\u062f\u064e\u062b \u0646\u064f\u0633\u0652\u062e\u064e\u0629 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644.","\u062e\u064e\u0644\u0627\u0635 \u0643\u0650\u062f\u064e\u0647. \u062f\u0650\u0644\u0652\u0648\u064e\u0642\u0652\u062a\u064a \u0627\u062f\u0652\u062e\u064f\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0642\u0650\u0633\u0652\u0645 \u0627\u0644\u0644\u064a \u0647\u064e\u062a\u0650\u0634\u0652\u062a\u064e\u063a\u064e\u0644 \u0641\u0650\u064a\u0647\u060c \u0648\u0643\u064f\u0644\u0651 \u0642\u0650\u0633\u0652\u0645 \u0644\u0650\u064a\u0647 \u0634\u064e\u0631\u0652\u062d \u062e\u0627\u0635\u0651 \u0628\u0650\u064a\u0647 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u062a\u0650\u0641\u0652\u062a\u064e\u062d\u064f\u0647. \u0648\u0644\u064e\u0648\u0652 \u0639\u0627\u064a\u0650\u0632 \u062a\u0652\u0639\u064a\u062f \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647\u060c \u0645\u0650\u0646 \u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a\u060c \u062f\u064f\u0648\u0633 \u0625\u0650\u0639\u0627\u062f\u0650\u0629 \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d.","\u0634\u0627\u0634\u0650\u0629 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641. \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u062f\u064a \u0628\u0650\u062a\u0650\u0641\u0652\u062a\u064e\u062d \u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u0645\u0652\u0633\u064e\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0635\u0650\u0646\u0652\u0641. \u0647\u064e\u0646\u0652\u0639\u064e\u062f\u0650\u0651\u064a \u0639\u064e\u0644\u0649 \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u064a\u0647\u0627 \u0648\u0627\u062d\u0652\u062f\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629.","\u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0645\u064e\u0633\u064e\u062d\u0652\u062a\u064f\u0647\u060c \u0645\u064e\u0643\u0652\u062a\u0648\u0628 \u0643\u0650\u0628\u064a\u0631 \u0647\u0650\u0646\u0627. \u0627\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u0625\u0650\u0646\u0651 \u0627\u0644\u0627\u0633\u0652\u0645 \u0647\u064f\u0648\u064e\u0651 \u0646\u064e\u0641\u0652\u0633 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0641\u064a \u0625\u0650\u064a\u062f\u064e\u0643\u060c \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u062a\u0650\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0639\u064e\u062f\u064e\u062f. \u0644\u064e\u0648\u0652 \u0645\u0650\u0634 \u0647\u064f\u0648\u064e\u0651\u060c \u062f\u064f\u0648\u0633 \u0631\u064f\u062c\u0648\u0639\u060c \u0648\u0627\u0645\u0652\u0633\u064e\u062d \u062a\u0627\u0646\u064a.","\u0635\u0648\u0631\u0650\u0629 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0644\u0650\u064a\u0647 \u0635\u0648\u0631\u064e\u0629 \u0641\u064a \u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c \u0627\u0644\u0628\u0650\u064a\u0639\u060c \u0628\u0650\u062a\u0650\u0638\u0652\u0647\u064e\u0631 \u0647\u0650\u0646\u0627 \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0650\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u0625\u0650\u0646\u064f\u0651\u0647 \u0647\u064f\u0648\u064e\u0651. \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0649 \u0627\u0644\u0635\u0651\u0648\u0631\u064e\u0629 \u062a\u0650\u0643\u0652\u0628\u064e\u0631\u060c \u0648\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0652\u0642\u064e\u0631\u064e\u0651\u0628 \u0628\u0650\u0635\u064f\u0628\u0627\u0639\u064a\u0646.","\u0627\u0646\u0652\u0637\u064f\u0642 \u0627\u0644\u0627\u0633\u0652\u0645. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u064a\u0650\u0642\u0648\u0644 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0628\u0650\u0635\u064f\u0648\u062a \u0639\u0627\u0644\u064a. \u0645\u064f\u0641\u064a\u062f \u0644\u064e\u0648\u0652 \u0625\u0650\u0646\u0652\u062a\u064e \u0628\u064e\u0639\u064a\u062f \u0639\u064e\u0646 \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629.","\u062a\u064e\u0646\u0652\u0628\u064a\u0647\u0627\u062a \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641. \u0633\u0627\u0639\u0627\u062a \u0647\u064e\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0641\u064f\u0648\u0642 \u0627\u0644\u0627\u0633\u0652\u0645 \u0645\u064f\u0631\u064e\u0628\u064e\u0651\u0639 \u0645\u0650\u0644\u064e\u0648\u0650\u0651\u0646. \u0644\u064e\u0648\u0652 \u0628\u064f\u0631\u0652\u062a\u064f\u0642\u0627\u0646\u064a\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0634\u064e\u0643\u0650\u0651\u0644: \u0639\u0650\u062f\u0651 \u0643\u064f\u0644\u0651 \u0627\u0644\u0623\u064e\u0644\u0652\u0648\u0627\u0646 \u0645\u064e\u0639\u064e \u0628\u064e\u0639\u0652\u0636. \u0644\u064e\u0648\u0652 \u0623\u064e\u062d\u0652\u0645\u064e\u0631\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0635\u0650\u0646\u0652\u0641 \u0639\u064e\u0631\u0652\u0636: \u0627\u0645\u0652\u0633\u064e\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0645\u0650\u0646 \u062c\u064f\u0648\u064e\u0651\u0647\u060c \u0645\u0650\u0634 \u0628\u0627\u0631\u0643\u0648\u062f \u0627\u0644\u0639\u064e\u0631\u0652\u0636. \u0644\u064e\u0648\u0652 \u0628\u064e\u0646\u064e\u0641\u0652\u0633\u0650\u062c\u064a\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0635\u0650\u0646\u0652\u0641 \u0628\u0650\u0627\u0644\u062e\u064e\u0635\u0652\u0645: \u0639\u0650\u062f\u0651 \u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0650\u064a\u0647 \u062e\u064e\u0635\u0652\u0645 \u0628\u064e\u0633\u0651.","\u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629. \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u062f\u064e\u0647 \u0647\u064e\u064a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u062f\u064a. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0641\u064a \u0645\u064e\u0643\u0627\u0646 \u062a\u0627\u0646\u064a \u063a\u0650\u064a\u0631 \u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u0627\u0644\u0644\u064a \u0625\u0650\u0646\u0652\u062a\u064e \u0641\u064a\u0647\u0627\u060c \u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u0627\u0644\u0635\u064e\u0651\u062d\u0651 \u0645\u0650\u0646 \u0647\u0650\u0646\u0627.","\u0627\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0628\u0650\u064a\u0650\u062a\u0652\u0628\u0627\u0639 \u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0647\u064e\u062a\u0652\u0644\u0627\u0642\u064a \u0627\u0644\u062e\u0627\u0646\u064e\u0629 \u062f\u064a\u060c \u0648\u0645\u064e\u0643\u0652\u062a\u0648\u0628 \u062c\u064e\u0646\u0652\u0628\u064e\u0647\u0627 \u0627\u0644\u0643\u064e\u0631\u0652\u062a\u0648\u0646\u064e\u0629 \u0641\u064a\u0647\u0627 \u0643\u0627\u0645 \u062d\u0650\u062a\u064e\u0651\u0629. \u0627\u0643\u0652\u062a\u0650\u0628 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646 \u0627\u0644\u0645\u064e\u0642\u0652\u0641\u0648\u0644\u064e\u0629 \u0628\u064e\u0633\u0651\u060c \u0648\u0627\u0644\u062d\u0650\u062a\u064e\u062a \u0627\u0644\u0641\u064e\u0643\u064e\u0651\u0629 \u0627\u0643\u0652\u062a\u0650\u0628\u0652\u0647\u0627 \u0641\u064a \u062e\u0627\u0646\u0650\u0629 \u0627\u0644\u0642\u0650\u0637\u064e\u0639.","\u0641\u064e\u0631\u0652\u0642 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0647\u064f\u0648\u064e\u0651 \u0627\u0644\u0641\u064e\u0631\u0652\u0642 \u0628\u064a\u0646 \u0627\u0644\u0644\u064a \u0625\u0650\u0646\u0652\u062a\u064e \u0639\u064e\u062f\u0650\u0651\u064a\u062a\u064f\u0647\u060c \u0648\u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645. \u0644\u064e\u0648\u0652 \u0623\u064e\u062e\u0652\u0636\u064e\u0631\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0645\u064e\u0638\u0652\u0628\u0648\u0637. \u0644\u064e\u0648\u0652 \u0623\u064e\u062d\u0652\u0645\u064e\u0631\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0641\u0650\u064a\u0647 \u0632\u0650\u064a\u0627\u062f\u064e\u0629 \u0623\u064e\u0648\u0652 \u0639\u064e\u062c\u0652\u0632. \u0648\u0644\u064e\u0648\u0652 \u0627\u0644\u0641\u064e\u0631\u0652\u0642 \u0643\u0650\u0628\u064a\u0631\u060c \u0639\u0650\u062f\u0651 \u062a\u0627\u0646\u064a \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u062a\u0650\u062d\u0652\u0641\u064e\u0638.","\u0627\u0644\u0643\u0650\u0645\u0650\u0651\u064a\u064e\u0651\u0629 \u0642\u064e\u0628\u0652\u0644 \u0648\u0628\u064e\u0639\u0652\u062f. \u0642\u064e\u0628\u0652\u0644\u060c \u0647\u0650\u064a\u064e\u0651 \u0627\u0644\u0643\u0650\u0645\u0650\u0651\u064a\u064e\u0651\u0629 \u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645. \u0648\u0628\u064e\u0639\u0652\u062f\u060c \u0647\u0650\u064a\u064e\u0651 \u0627\u0644\u0644\u064a \u0647\u064e\u062a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0628\u064e\u0639\u0652\u062f \u0639\u064e\u062f\u064e\u0651\u0643.","\u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0642\u0650\u0637\u064e\u0639. \u0627\u0643\u0652\u062a\u0650\u0628 \u0647\u0650\u0646\u0627 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u062d\u0650\u062a\u064e\u062a \u0627\u0644\u0644\u064a \u0639\u064e\u062f\u0650\u0651\u064a\u062a\u0652\u0647\u0627. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0645\u064e\u0648\u0652\u062c\u0648\u062f \u0641\u064a \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u0645\u064e\u0643\u0627\u0646\u060c \u0639\u0650\u062f\u0651 \u0627\u0644\u0644\u064a \u0642\u064f\u062f\u0651\u0627\u0645\u064e\u0643 \u0648\u0627\u062d\u0652\u0641\u064e\u0638\u060c \u0648\u0644\u064e\u0645\u0651\u0627 \u062a\u0652\u0644\u0627\u0642\u064a\u0647 \u0641\u064a \u0645\u064e\u0643\u0627\u0646 \u062a\u0627\u0646\u064a\u060c \u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0647 \u062a\u0627\u0646\u064a\u060c \u0648\u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0639\u064e\u062f\u064e\u062f \u0641\u064a \u0627\u0644\u062e\u0627\u0646\u064e\u0629 \u0627\u0644\u0644\u064a \u0628\u064e\u0639\u0652\u062f\u064e\u0647\u0627\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0628\u0650\u064a\u0650\u062c\u0652\u0645\u064e\u0639\u0652\u0647\u064f\u0645 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647.","\u062a\u064e\u0639\u0652\u062f\u064a\u0644 \u062e\u0627\u0646\u064e\u0629 \u0642\u064e\u062f\u064a\u0645\u064e\u0629. \u0644\u064e\u0648\u0652 \u0643\u064e\u062a\u064e\u0628\u0652\u062a \u0631\u064e\u0642\u064e\u0645 \u063a\u064e\u0644\u064e\u0637 \u0642\u064e\u0628\u0652\u0644 \u0643\u0650\u062f\u064e\u0647\u060c \u062f\u064f\u0648\u0633 \u0641\u064e\u062a\u0652\u062d \u0627\u0644\u062a\u064e\u0651\u0639\u0652\u062f\u064a\u0644\u060c \u0648\u0635\u064e\u0644\u064e\u0651\u062d \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0641\u064a \u0627\u0644\u062e\u0627\u0646\u064e\u0629 \u0628\u0650\u062a\u0627\u0639\u0652\u062a\u064f\u0647\u060c \u0648\u0627\u062d\u0652\u0641\u064e\u0638. \u0648\u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0627 \u0631\u064e\u062c\u064e\u0651\u0639\u0652\u0647\u0627 \u0642\u064e\u0641\u0652\u0644 \u0627\u0644\u062a\u064e\u0651\u0639\u0652\u062f\u064a\u0644\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u0645\u0627 \u062a\u0652\u063a\u064e\u064a\u064e\u0651\u0631\u0652\u0634 \u062d\u0627\u062c\u064e\u0629 \u0628\u0650\u0627\u0644\u063a\u064e\u0644\u064e\u0637.","\u0627\u0644\u062d\u0650\u0641\u0652\u0638. \u0632\u064f\u0631\u0627\u0631 \u062d\u0650\u0641\u0652\u0638 \u0627\u0644\u062a\u064e\u0651\u0627\u0644\u064a\u060c \u0628\u0650\u064a\u0650\u062d\u0652\u0641\u064e\u0638 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641\u060c \u0648\u064a\u0652\u0631\u064e\u062c\u064e\u0651\u0639\u064e\u0643 \u0644\u0650\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644 \u0644\u0650\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0628\u064e\u0639\u0652\u062f\u064f\u0647. \u0648\u0632\u064f\u0631\u0627\u0631 \u0631\u064f\u062c\u0648\u0639\u060c \u0628\u0650\u064a\u0650\u0642\u0652\u0641\u0650\u0644 \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0645\u0627 \u064a\u0650\u062d\u0652\u0641\u064e\u0638 \u062d\u0627\u062c\u064e\u0629.","\u062a\u064a\u0643\u0650\u062a \u0627\u0644\u0645\u064a\u0632\u0627\u0646. \u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u0645\u0652\u0633\u064e\u062d \u062a\u064a\u0643\u0650\u062a \u0645\u064a\u0632\u0627\u0646\u060c \u0627\u0644\u0648\u064e\u0632\u0652\u0646 \u0627\u0644\u0645\u064e\u0637\u0652\u0628\u0648\u0639 \u0639\u064e\u0644\u0650\u064a\u0647 \u0628\u0650\u064a\u0650\u062a\u0652\u0643\u0650\u062a\u0650\u0628 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647. \u0648\u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0641\u064a \u062c\u064e\u0631\u0652\u062f\u064e\u0644 \u0623\u064e\u0648\u0652 \u0639\u064f\u0644\u0652\u0628\u064e\u0629\u060c \u0627\u0643\u0652\u062a\u0650\u0628 \u0648\u064e\u0632\u0652\u0646 \u0627\u0644\u0648\u0650\u0639\u0627\u0621 \u0628\u0650\u0627\u0644\u062c\u0650\u0631\u0627\u0645 \u0641\u064a \u062e\u0627\u0646\u0652\u062a\u064f\u0647\u060c \u0648\u0647\u064f\u0648\u064e\u0651 \u064a\u0650\u062a\u0652\u062e\u0650\u0635\u0650\u0645 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651 \u062a\u064a\u0643\u0650\u062a\u060c \u0648\u064a\u0650\u0641\u0652\u0636\u064e\u0644 \u0645\u064e\u062d\u0652\u0641\u0648\u0638 \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u062a\u0652\u063a\u064e\u064a\u064e\u0651\u0631\u064f\u0647.","\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062c\u0650\u062f\u064a\u062f\u064e\u0629. \u0645\u0650\u0646 \u0647\u0650\u0646\u0627 \u0628\u0650\u062a\u0650\u0628\u0652\u062f\u064e\u0623 \u0623\u064e\u064a\u0651 \u0641\u0627\u062a\u0648\u0631\u064e\u0629: \u0628\u0650\u062a\u0652\u0635\u064e\u0648\u064e\u0651\u0631\u0652\u0647\u0627\u060c \u0648\u062a\u0650\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f\u060c \u0648\u062a\u0650\u0639\u0652\u0645\u0650\u0644 \u0633\u0652\u0643\u0627\u0646 \u0644\u0650\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u0648\u062a\u0650\u0628\u0652\u0639\u064e\u062a\u0652\u0647\u0627 \u0644\u0650\u0644\u062f\u064e\u0651\u0639\u0652\u0645.","\u0627\u0644\u0641\u064e\u0631\u0652\u0639. \u0644\u064e\u0648\u0652 \u0644\u0650\u064a\u0643 \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u0641\u064e\u0631\u0652\u0639\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0644\u064a \u0625\u0650\u0646\u0652\u062a\u064e \u0634\u064e\u063a\u0651\u0627\u0644 \u0639\u064e\u0644\u0650\u064a\u0647.","\u0633\u0650\u062c\u0650\u0644\u0651 \u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631. \u0643\u064f\u0644\u0651 \u0641\u064e\u0648\u0627\u062a\u064a\u0631\u064e\u0643 \u0647\u0650\u0646\u0627. \u0627\u062e\u0652\u062a\u0627\u0631: \u0627\u0644\u0645\u064f\u0633\u064e\u0648\u064e\u0651\u062f\u0627\u062a\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0645\u0650\u0633\u0652\u062a\u064e\u0646\u0650\u0651\u064a\u064e\u0629 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0644\u064a \u062f\u064e\u062e\u064e\u0644\u0650\u062a\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0644\u064a \u0645\u0650\u062d\u0652\u062a\u0627\u062c\u064e\u0629 \u0645\u064f\u0631\u0627\u062c\u064e\u0639\u0652\u062a\u064e\u0643\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0645\u064e\u0631\u0652\u0641\u0648\u0636\u064e\u0629.","\u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0627\u0644\u0641\u064e\u0646\u0650\u0651\u064a. \u0639\u064e\u0646\u0652\u062f\u064e\u0643 \u0645\u064f\u0634\u0652\u0643\u0650\u0644\u064e\u0629 \u0641\u064a \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0637\u064e\u0651\u0627\u0628\u0652\u0639\u064e\u0629\u060c \u0623\u064e\u0648\u0652 \u0645\u0650\u062d\u0652\u062a\u0627\u062c \u062d\u0650\u0633\u0627\u0628 \u062c\u0650\u062f\u064a\u062f\u061f \u0645\u0650\u0646 \u0647\u0650\u0646\u0627 \u062a\u0650\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u064f\u0634\u0652\u0643\u0650\u0644\u064e\u0629\u060c \u0648\u062a\u0652\u062c\u064e\u0631\u064e\u0651\u0628 \u0627\u0644\u062d\u064e\u0644\u0651 \u0627\u0644\u0633\u064e\u0651\u0631\u064a\u0639\u060c \u0648\u0644\u064e\u0648\u0652 \u0645\u0627 \u0627\u062a\u0652\u062d\u064e\u0644\u0650\u0651\u062a\u0652\u0634\u060c \u062a\u064f\u0637\u0652\u0644\u064f\u0628 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645\u060c \u0648\u062a\u0650\u062a\u0627\u0628\u0650\u0639 \u0637\u064e\u0644\u064e\u0628\u064e\u0643 \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u064a\u0650\u062a\u0652\u062d\u064e\u0644\u0651.","\u0634\u0627\u062a \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645. \u0643\u064e\u0644\u0650\u0651\u0645 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0641\u064a \u0623\u064e\u064a\u0651 \u062d\u0627\u062c\u064e\u0629 \u062a\u0650\u062e\u064f\u0635\u0651 \u0627\u0644\u0641\u064e\u0631\u0652\u0639\u060c \u0648\u0627\u0628\u0652\u0639\u064e\u062a \u0635\u064f\u0648\u064e\u0631 \u0643\u064e\u0645\u0627\u0646. \u0647\u064e\u062a\u0652\u0634\u0648\u0641 \u0639\u064e\u0644\u0627\u0645\u064e\u0629 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0634\u0627\u0641\u0652\u0647\u0627 \u0644\u064e\u0645\u0651\u0627 \u064a\u0650\u0642\u0652\u0631\u064f\u0648\u0627 \u0631\u0650\u0633\u0627\u0644\u0652\u062a\u064e\u0643\u060c \u0648\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0623\u064e\u062d\u0652\u0645\u064e\u0631\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0631\u064e\u062f\u0651 \u062c\u0650\u062f\u064a\u062f.","\u0627\u0644\u0625\u0650\u0634\u0652\u0639\u0627\u0631\u0627\u062a. \u0643\u064f\u0644\u0651 \u0623\u064e\u062e\u0652\u0628\u0627\u0631 \u0641\u064e\u0648\u0627\u062a\u064a\u0631\u064e\u0643 \u0623\u064e\u0648\u0650\u0651\u0644 \u0628\u0650\u0623\u064e\u0648\u0650\u0651\u0644: \u0627\u062a\u0652\u0631\u064e\u0641\u064e\u0639\u0650\u062a\u060c \u0627\u0633\u0652\u062a\u064e\u0644\u064e\u0645\u0652\u0647\u0627 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645\u060c \u062f\u064e\u062e\u064e\u0644\u0650\u062a \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645.","\u062f\u064e\u0644\u064a\u0644 \u0627\u0644\u0627\u0633\u0652\u062a\u0650\u062e\u0652\u062f\u0627\u0645. \u0644\u064e\u0648\u0652 \u0646\u0650\u0633\u064a\u062a \u0623\u064e\u064a\u0651 \u062d\u0627\u062c\u064e\u0629\u060c \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u0643\u064f\u0644\u064f\u0651\u0647 \u0647\u0650\u0646\u0627 \u062e\u064f\u0637\u0652\u0648\u064e\u0629 \u0628\u0650\u062e\u064f\u0637\u0652\u0648\u064e\u0629.","\u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629. \u0641\u064a\u0647\u0627 \u0635\u0648\u0631\u0652\u062a\u064e\u0643\u060c \u0648\u062a\u064e\u063a\u0652\u064a\u064a\u0631 \u0627\u0644\u0641\u064e\u0631\u0652\u0639\u060c \u0648\u0646\u064f\u0637\u0652\u0642 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641\u060c \u0648\u0644\u064f\u0648\u062d\u0650\u0629 \u0627\u0644\u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0627\u0644\u0643\u0650\u0628\u064a\u0631\u064e\u0629\u060c \u0648\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0652\u0639\u064a\u062f \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647 \u0645\u0650\u0646 \u0647\u0650\u0646\u0627\u0643.","\u0635\u064e\u0648\u064e\u0651\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0623\u064e\u0648\u0650\u0651\u0644 \u062d\u0627\u062c\u064e\u0629\u060c \u0635\u064e\u0648\u064e\u0651\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0627\u0644\u0648\u064e\u0631\u064e\u0642. \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0628\u0650\u064a\u0652\u0642\u064f\u0635\u0651 \u0627\u0644\u0635\u0651\u0648\u0631\u064e\u0629 \u0639\u064e\u0644\u0649 \u0642\u064e\u062f\u0651 \u0627\u0644\u0648\u064e\u0631\u064e\u0642\u064e\u0629 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647\u060c \u0648\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0652\u0636\u064a\u0641 \u0643\u064e\u0630\u0627 \u0635\u064e\u0641\u0652\u062d\u064e\u0629.","\u0627\u0644\u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f. \u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u064f\u0648\u064e\u0631\u0650\u0651\u062f \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629\u060c \u0623\u064e\u0648\u0652 \u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0633\u0652\u0645\u064f\u0647 \u0644\u064e\u0648\u0652 \u062c\u0650\u062f\u064a\u062f.","\u0625\u0650\u062c\u0652\u0645\u0627\u0644\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0647\u0650\u0646\u0627 \u0628\u0650\u064a\u0650\u062a\u0652\u062c\u0650\u0645\u0650\u0639 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u0648\u0625\u0650\u062c\u0652\u0645\u0627\u0644\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629\u060c \u0648\u0625\u0650\u0646\u0652\u062a\u064e \u0634\u064e\u063a\u0651\u0627\u0644.","\u0633\u0652\u0643\u0627\u0646 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0648\u064e\u062c\u0650\u0651\u0647 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0639\u064e\u0644\u0649 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f. \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0647\u064e\u064a\u0652\u0642\u0648\u0644 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641\u060c \u0648\u0625\u0650\u0646\u0652\u062a\u064e \u062a\u0650\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0643\u0650\u0645\u0650\u0651\u064a\u064e\u0651\u0629\u060c \u0648\u0625\u0650\u062c\u0652\u0645\u0627\u0644\u064a \u0633\u0650\u0639\u0652\u0631\u064f\u0647.","\u0628\u0650\u0627\u0644\u0627\u0633\u0652\u0645. \u0644\u064e\u0648\u0652 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \u0645\u0650\u0634 \u0634\u064e\u063a\u0651\u0627\u0644\u060c \u062f\u064e\u0648\u064e\u0651\u0631 \u0639\u064e\u0644\u0649 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0628\u0650\u0627\u0633\u0652\u0645\u064f\u0647\u060c \u0623\u064e\u0648\u0652 \u0627\u0643\u0652\u062a\u0650\u0628 \u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f.","\u0631\u0627\u062c\u0650\u0639 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062f\u064e\u062e\u064e\u0644\u0650\u062a \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0642\u0627\u0631\u0650\u0646 \u0635\u0648\u0631\u0650\u062a\u0652\u0647\u0627 \u0628\u0650\u0635\u0648\u0631\u0650\u0629 \u0627\u0644\u0633\u0650\u0651\u064a\u0633\u0652\u062a\u0650\u0645\u060c \u0648\u0628\u064e\u0639\u0652\u062f\u064a\u0646 \u062f\u064f\u0648\u0633 \u062a\u064e\u0645\u0627\u0645\u060c \u0623\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0645\u064f\u0644\u0627\u062d\u0652\u0638\u064e\u0629. \u0645\u064f\u0647\u0650\u0645\u0651: \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0641\u0627\u062a\u0648\u0631\u0652\u062a\u064a\u0646 \u0645\u0650\u0633\u0652\u062a\u064e\u0646\u0650\u0651\u064a\u064a\u0646 \u0645\u064f\u0631\u0627\u062c\u064e\u0639\u064e\u0629\u060c \u0645\u0650\u0634 \u0647\u064e\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0650\u0628\u0652\u0639\u064e\u062a \u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062c\u0650\u062f\u064a\u062f\u064e\u0629.","\u0643\u064e\u0644\u0650\u0651\u0645 \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0639\u064e\u0646 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0644\u064e\u0648\u0652 \u0639\u064e\u0646\u0652\u062f\u064e\u0643 \u0633\u064f\u0624\u0627\u0644\u060c \u0623\u064e\u0648\u0652 \u0639\u0627\u064a\u0650\u0632 \u062a\u0650\u0628\u0652\u0639\u064e\u062a \u0635\u0648\u0631\u064e\u0629 \u062a\u0627\u0646\u0652\u064a\u064e\u0629 \u0644\u0650\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062f\u064a\u060c \u0627\u0643\u0652\u062a\u0650\u0628 \u0647\u0650\u0646\u0627. \u0627\u0644\u0631\u0650\u0651\u0633\u0627\u0644\u064e\u0629 \u0628\u0650\u062a\u064f\u0648\u0635\u064e\u0644 \u0644\u0650\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644\u060c \u0648\u0647\u064e\u062a\u0650\u0639\u0652\u0631\u064e\u0641 \u0644\u064e\u0645\u0651\u0627 \u064a\u0652\u0634\u0648\u0641\u0648\u0647\u0627.","\u062a\u064e\u0642\u0652\u0631\u064a\u0631 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0644\u064a \u0633\u0650\u0639\u0652\u0631\u064e\u0647\u0627 \u0632\u0627\u062f \u0623\u064e\u0648\u0652 \u0642\u064e\u0644\u0651. \u0628\u0650\u062a\u0650\u0641\u0652\u062a\u064e\u062d\u064f\u0647 \u0628\u064a \u062f\u064a \u0625\u0650\u0641 \u0623\u064e\u0648\u0652 \u0625\u0650\u0643\u0652\u0633\u0650\u0644\u060c \u0648\u062a\u0650\u0628\u0652\u0639\u064e\u062a\u064f\u0647 \u0644\u0650\u0644\u0645\u064f\u062f\u064a\u0631 \u0639\u064e\u0644\u0649 \u0648\u0627\u062a\u0652\u0633\u0627\u0628 \u0628\u0650\u062f\u0648\u0633\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629.","\u0627\u0633\u0652\u062a\u0650\u0639\u0652\u062c\u0627\u0644 \u0627\u0644\u0625\u0650\u062f\u0652\u062e\u0627\u0644. \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0645\u0650\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644\u064e\u0629\u061f \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645 \u064a\u064f\u0648\u0635\u064e\u0644\u064f\u0647 \u062a\u064e\u0646\u0652\u0628\u064a\u0647. \u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0650\u0633\u0652\u062a\u064e\u0639\u0652\u062c\u0650\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u0643\u064f\u0644\u0651 \u062e\u064e\u0645\u064e\u0633 \u062f\u064e\u0642\u0627\u064a\u0650\u0642\u060c \u0648\u0627\u0644\u0632\u064f\u0651\u0631\u0627\u0631 \u0628\u0650\u064a\u0650\u062e\u0652\u062a\u0650\u0641\u064a \u0628\u064e\u0631\u064e\u0651\u0647 \u0645\u064e\u0648\u0627\u0639\u064a\u062f \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645.","\u0627\u0628\u0652\u0639\u064e\u062a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629. \u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u062e\u064e\u0644\u064e\u0651\u0635 \u0643\u064f\u0644\u0651 \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627. \u0647\u064e\u064a\u064f\u0637\u0652\u0644\u064f\u0628 \u0645\u0650\u0646\u064e\u0651\u0643 \u062a\u0650\u0643\u0652\u062a\u0650\u0628 \u0625\u0650\u062c\u0652\u0645\u0627\u0644\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0645\u0650\u0646 \u0627\u0644\u0648\u064e\u0631\u064e\u0642\u064e\u0629\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u0646\u0650\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u0625\u0650\u0646\u0651 \u0643\u064f\u0644\u064f\u0651\u0647 \u0645\u064e\u0638\u0652\u0628\u0648\u0637.","\u0645\u064a\u0646 \u0627\u0644\u0644\u064a \u0647\u064e\u064a\u0650\u0634\u0652\u062a\u064e\u063a\u064e\u0644\u061f \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u062f\u064e\u0647 \u0628\u0650\u064a\u0650\u0641\u0652\u062a\u0650\u0643\u0650\u0631 \u0643\u064f\u0644\u0651 \u0645\u064f\u0648\u064e\u0638\u064e\u0651\u0641 \u062f\u064e\u062e\u064e\u0644 \u0639\u064e\u0644\u0650\u064a\u0647 \u0642\u064e\u0628\u0652\u0644 \u0643\u0650\u062f\u064e\u0647\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0628\u0650\u0633\u064f\u0631\u0652\u0639\u064e\u0629\u060c \u0648\u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0646\u0650\u062a\u0651.","\u0627\u0633\u0652\u0645\u064e\u0643. \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0649 \u0627\u0633\u0652\u0645\u064e\u0643\u060c \u0648\u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0633\u0650\u0651\u0631\u0650\u0651\u064a \u0628\u0650\u062a\u0627\u0639\u064e\u0643\u060c \u0648\u062f\u064f\u0648\u0633 \u062f\u064f\u062e\u0648\u0644. \u062f\u064e\u0647 \u0628\u0650\u064a\u0650\u0634\u0652\u062a\u064e\u063a\u064e\u0644 \u062d\u064e\u062a\u0651\u0649 \u0644\u064e\u0648\u0652 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0642\u0627\u0637\u0650\u0639\u060c \u0648\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u063a\u064e\u0644\u064e\u0637 \u0628\u0650\u064a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0636.","\u0634\u0650\u064a\u0644 \u0627\u0644\u0627\u0633\u0652\u0645 \u0645\u0650\u0646 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644. \u0644\u064e\u0648\u0652 \u0645\u064f\u0648\u064e\u0638\u064e\u0651\u0641 \u0633\u0627\u0628 \u0627\u0644\u0634\u064f\u0651\u063a\u0652\u0644\u060c \u0623\u064e\u0648\u0652 \u0645\u0650\u0634 \u0647\u064e\u064a\u0650\u0633\u0652\u062a\u064e\u062e\u0652\u062f\u0650\u0645 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u062f\u064e\u0647 \u062a\u0627\u0646\u064a\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u0648\u0634\u0650\u064a\u0644 \u0627\u0633\u0652\u0645\u064f\u0647. \u0648\u0644\u064e\u0648\u0652 \u0631\u0650\u062c\u0650\u0639\u060c \u0647\u064e\u064a\u0650\u062f\u0652\u062e\u064f\u0644 \u062a\u0627\u0646\u064a \u0639\u0627\u062f\u064a\u060c \u0628\u064e\u0633\u0651 \u0645\u0650\u062d\u0652\u062a\u0627\u062c \u0646\u0650\u062a\u0651 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629.","\u062f\u064f\u062e\u0648\u0644 \u0645\u064f\u0648\u064e\u0638\u064e\u0651\u0641 \u062a\u0627\u0646\u064a. \u0644\u064e\u0648\u0652 \u0627\u0633\u0652\u0645\u064e\u0643 \u0645\u0650\u0634 \u0645\u064e\u0648\u0652\u062c\u0648\u062f \u0641\u064a \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629\u060c \u064a\u064e\u0639\u0652\u0646\u064a \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u062f\u064e\u0647\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u062f\u0652\u062e\u064f\u0644 \u0628\u0650\u0627\u0633\u0652\u0645\u064e\u0643 \u0648\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0633\u0650\u0651\u0631\u0650\u0651\u064a. \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u0628\u064e\u0633\u0651 \u0645\u0650\u062d\u0652\u062a\u0627\u062c\u064e\u0629 \u0646\u0650\u062a\u0651\u060c \u0648\u0628\u064e\u0639\u0652\u062f \u0643\u0650\u062f\u064e\u0647 \u0627\u0633\u0652\u0645\u064e\u0643 \u0647\u064e\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0641\u064a \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629.","\u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u0627\u0644\u062e\u064f\u0631\u0648\u062c. \u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u062e\u0652\u0644\u064e\u0635 \u0634\u064f\u063a\u0652\u0644\u064e\u0643\u060c \u0627\u0639\u0652\u0645\u0650\u0644 \u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u062e\u064f\u0631\u0648\u062c \u0645\u0650\u0646 \u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a. \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u0628\u0650\u064a\u0652\u0631\u0652\u062c\u064e\u0639 \u0644\u0650\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629 \u062f\u064a\u060c \u0648\u0632\u064e\u0645\u064a\u0644\u064e\u0643 \u064a\u0650\u062f\u0652\u062e\u064f\u0644 \u0628\u0650\u0627\u0633\u0652\u0645\u064f\u0647. \u0648\u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0633\u064e\u062c\u0650\u0651\u0644\u0652\u062a\u064e\u0647\u0627 \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0646\u0650\u062a\u0651\u060c \u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639 \u0628\u0650\u0627\u0633\u0652\u0645\u064e\u0643 \u0625\u0650\u0646\u0652\u062a\u064e.","\u0623\u064e\u0648\u0650\u0651\u0644 \u062f\u064f\u062e\u0648\u0644. \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u062f\u064e\u0647\u060c \u0647\u064e\u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0645\u0650\u0646 \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u062f\u064a\u060c \u0648\u0645\u0650\u062d\u0652\u062a\u0627\u062c \u0646\u0650\u062a\u0651 \u0627\u0644\u0645\u064e\u0631\u064e\u0651\u0629 \u062f\u064a \u0628\u064e\u0633\u0651.","\u0627\u0643\u0652\u062a\u0650\u0628 \u0631\u064e\u0642\u064e\u0645 \u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u064e\u0643\u060c \u0623\u064e\u0648\u0652 \u0627\u0633\u0652\u0645\u064e\u0643\u060c \u0623\u064e\u0648\u0652 \u0627\u0644\u0625\u064a\u0645\u064a\u0644\u060c \u0632\u064e\u064a\u0651 \u0645\u0627 \u0627\u0644\u0645\u064f\u062f\u064a\u0631 \u0633\u064e\u062c\u0650\u0651\u0644\u064e\u0643 \u0628\u0650\u0627\u0644\u0638\u064e\u0651\u0628\u0652\u0637.","\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0633\u0650\u0651\u0631\u0650\u0651\u064a. \u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0633\u0650\u0651\u0631\u0650\u0651\u064a \u0627\u0644\u0644\u064a \u0627\u0644\u0645\u064f\u062f\u064a\u0631 \u0627\u0650\u062f\u0651\u0627\u0647\u0648\u0644\u064e\u0643. \u0627\u0644\u0639\u0650\u064a\u0646 \u0627\u0644\u0644\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u062c\u064e\u0646\u0652\u0628 \u0628\u0650\u062a\u0652\u0648\u064e\u0631\u0651\u064a\u0643 \u0627\u0644\u0644\u064a \u0643\u064e\u062a\u064e\u0628\u0652\u062a\u064f\u0647.","\u0645\u0650\u062d\u0652\u062a\u0627\u062c \u0646\u0650\u062a\u0651 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629 \u0628\u064e\u0633\u0651. \u0644\u064e\u0648\u0652 \u0645\u064e\u0641\u064a\u0634 \u0646\u0650\u062a\u0651 \u0641\u064a \u0627\u0644\u0645\u064e\u062d\u064e\u0644\u0651\u060c \u0634\u064e\u063a\u064e\u0651\u0644 \u0646\u0650\u062a\u0651 \u0645\u0650\u0646 \u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u064e\u0643 \u062b\u064e\u0648\u0627\u0646\u064a\u060c \u0648\u0627\u062f\u0652\u062e\u064f\u0644. \u0628\u064e\u0639\u0652\u062f \u0643\u0650\u062f\u064e\u0647 \u0627\u0633\u0652\u0645\u064e\u0643 \u0647\u064e\u064a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u060c \u0648\u0647\u064e\u062a\u0650\u062f\u0652\u062e\u064f\u0644 \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0646\u0650\u062a\u0651.","\u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u0628\u064e\u0639\u0652\u062f \u0645\u0627 \u062a\u0650\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0627\u0633\u0652\u0645\u060c \u0648\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0633\u0650\u0651\u0631\u0650\u0651\u064a.","\u0623\u064e\u0647\u0652\u0644\u064b\u0627 \u0628\u0650\u064a\u0643 \u0641\u064a \u0634\u0627\u0634\u0650\u0629 \u0627\u0644\u062c\u064e\u0631\u0652\u062f. \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647 \u0647\u064e\u064a\u0652\u0639\u064e\u062f\u0650\u0651\u064a \u0645\u064e\u0639\u0627\u0643 \u0639\u064e\u0644\u0649 \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u064a \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629. \u062f\u064f\u0648\u0633 \u0627\u0644\u062a\u064e\u0651\u0627\u0644\u064a \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0652\u0643\u064e\u0645\u0650\u0651\u0644\u060c \u0648\u0631\u064f\u062c\u0648\u0639 \u0644\u064e\u0648\u0652 \u0639\u0627\u064a\u0650\u0632 \u062a\u0650\u0631\u0652\u062c\u064e\u0639 \u0644\u0650\u0644\u0651\u064a \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u0627. \u0648\u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0652\u0639\u064a\u062f \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647 \u0641\u064a \u0623\u064e\u064a\u0651 \u0648\u064e\u0642\u0652\u062a \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629.","\u0627\u0633\u0652\u0645 \u0627\u0644\u0641\u064e\u0631\u0652\u0639. \u062f\u064e\u0647 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0644\u064a \u0628\u0650\u062a\u0650\u062c\u0652\u0631\u064f\u062f \u0641\u0650\u064a\u0647 \u062f\u0650\u0644\u0652\u0648\u064e\u0642\u0652\u062a\u064a. \u0644\u064e\u0648\u0652 \u0644\u0650\u064a\u0643 \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u0641\u064e\u0631\u0652\u0639\u060c \u0647\u064e\u062a\u0652\u0644\u0627\u0642\u064a \u0633\u064e\u0647\u0652\u0645 \u0635\u064f\u063a\u064e\u064a\u064e\u0651\u0631 \u062c\u064e\u0646\u0652\u0628\u064f\u0647\u060c \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647\u060c \u0648\u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0635\u064e\u0651\u062d\u0651 \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u062a\u0650\u0628\u0652\u062f\u064e\u0623. \u0627\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u062f\u0627\u064a\u0652\u0645\u064b\u0627 \u0625\u0650\u0646\u064e\u0651\u0643 \u0639\u064e\u0644\u0649 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u0627\u0644\u0635\u064e\u0651\u062d\u0651.","\u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u0627\u0644\u0644\u064a \u0628\u0650\u062a\u0650\u062c\u0652\u0631\u064f\u062f \u0641\u064a\u0647\u0627. \u062a\u064e\u062d\u0652\u062a \u0627\u0633\u0652\u0645 \u0627\u0644\u0641\u064e\u0631\u0652\u0639\u060c \u0645\u064e\u0643\u0652\u062a\u0648\u0628 \u0625\u0650\u0646\u0652\u062a\u064e \u0628\u0650\u062a\u0650\u062c\u0652\u0631\u064f\u062f \u0641\u064a \u0623\u064e\u0646\u0652\u0647\u064a \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629: \u0631\u064e\u0641\u0651\u060c \u0623\u064e\u0648\u0652 \u0645\u064e\u0645\u064e\u0631\u0651\u060c \u0623\u064e\u0648\u0652 \u0645\u064e\u062e\u0652\u0632\u064e\u0646. \u0643\u064f\u0644\u0651 \u0635\u0650\u0646\u0652\u0641 \u0628\u0650\u062a\u0650\u062c\u0652\u0631\u064f\u062f\u064f\u0647 \u0628\u0650\u064a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u062f\u064a\u060c \u0641\u064e\u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u0646\u0652\u0642\u0650\u0644 \u0644\u0650\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629 \u062a\u0627\u0646\u0652\u064a\u064e\u0629\u060c \u063a\u064e\u064a\u064e\u0651\u0631\u0652\u0647\u0627 \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629.","\u0632\u064f\u0631\u0627\u0631 \u062e\u0650\u0644\u0650\u0635\u0652\u062a. \u062f\u064e\u0647 \u0623\u064e\u0647\u064e\u0645\u0651 \u0632\u064f\u0631\u0627\u0631 \u0641\u064a \u0622\u062e\u0650\u0631 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0644\u0627\u0632\u0650\u0645 \u062a\u0650\u062f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647 \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u062a\u0650\u0645\u0652\u0634\u064a. \u0648\u0625\u0650\u0646\u0652\u062a\u064e \u0628\u0650\u062a\u0650\u062c\u0652\u0631\u064f\u062f\u060c \u0628\u0650\u064a\u0650\u0628\u0652\u0642\u0649 \u0628\u0627\u0647\u0650\u062a\u060c \u0648\u062c\u064f\u0648\u0651\u0627\u0647 \u0631\u064e\u0642\u064e\u0645\u060c \u0647\u064f\u0648\u064e\u0651 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0644\u064a \u0644\u0650\u0633\u064e\u0651\u0647 \u0639\u064e\u0644\u0649 \u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u064e\u0643 \u0648\u0645\u0627 \u0648\u0650\u0635\u0652\u0644\u0650\u062a\u0652\u0634. \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0628\u0650\u064a\u0652\u0642\u0650\u0644\u0651 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647. \u0648\u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u064a\u0650\u062e\u0652\u0644\u064e\u0635\u060c \u0627\u0644\u0632\u064f\u0651\u0631\u0627\u0631 \u0628\u0650\u064a\u0652\u0642\u0652\u0644\u0650\u0628 \u0623\u064e\u062e\u0652\u0636\u064e\u0631\u060c \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647 \u0633\u0627\u0639\u0650\u062a\u0652\u0647\u0627.","\u062d\u0627\u0644\u0650\u0629 \u0627\u0644\u0646\u0650\u0651\u062a\u0651. \u0627\u0644\u0633\u064e\u0651\u062d\u0627\u0628\u064e\u0629 \u062f\u064a \u0628\u0650\u062a\u0652\u0642\u0648\u0644\u064e\u0651\u0643 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0639\u0627\u0645\u0650\u0644 \u0625\u0650\u064a\u0647. \u0644\u064e\u0648\u0652 \u0639\u0627\u062f\u0652\u064a\u064e\u0629\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0634\u064e\u063a\u0651\u0627\u0644. \u0644\u064e\u0648\u0652 \u0639\u064e\u0644\u0650\u064a\u0647\u0627 \u0639\u064e\u0644\u0627\u0645\u064e\u0629\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0628\u064e\u0637\u064a\u0621 \u0623\u064e\u0648\u0652 \u0642\u0627\u0637\u0650\u0639. \u0644\u064e\u0648\u0652 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0642\u0650\u0637\u0650\u0639\u060c \u0643\u064e\u0645\u0650\u0651\u0644 \u062c\u064e\u0631\u0652\u062f \u0639\u0627\u062f\u064a\u060c \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0628\u0650\u062a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u060c \u0648\u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064e\u0647\u0627 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u064a\u0650\u0631\u0652\u062c\u064e\u0639.","\u0627\u0644\u0631\u064e\u0651\u0641\u0652\u0639 \u0644\u0650\u0644\u0634\u0650\u0651\u064a\u062a. \u0647\u0650\u0646\u0627 \u0628\u0650\u062a\u0652\u0634\u0648\u0641 \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0644\u0650\u0633\u064e\u0651\u0647 \u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639. \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0631\u064e\u0642\u064e\u0645 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u0627\u0645\u064e\u0629 \u0628\u0650\u062a\u0652\u0644\u0650\u0641\u0651\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0641\u0650\u064a\u0647 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0645\u0650\u0633\u0652\u062a\u064e\u0646\u0650\u0651\u064a\u064e\u0629. \u0648\u0644\u064e\u0648\u0652 \u0641\u0627\u0636\u064a\u060c \u064a\u0650\u0628\u0652\u0642\u0649 \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0648\u0650\u0635\u0652\u0644\u0650\u062a.","\u062a\u064e\u062d\u0652\u062f\u064a\u062b \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u0644\u064e\u0648\u0652 \u0627\u0644\u0625\u0650\u062f\u0627\u0631\u064e\u0629 \u0636\u0627\u0641\u0650\u062a \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u062c\u0650\u062f\u064a\u062f\u064e\u0629\u060c \u0623\u064e\u0648\u0652 \u0644\u064e\u0648\u0652 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0634 \u0644\u0627\u0642\u064a\u0647\u060c \u0648\u0625\u0650\u0646\u0652\u062a\u064e \u0645\u0650\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u0625\u0650\u0646\u064f\u0651\u0647 \u0645\u064e\u0648\u0652\u062c\u0648\u062f. \u0628\u0650\u064a\u0652\u062c\u064a\u0628 \u0622\u062e\u0650\u0631 \u0646\u064f\u0633\u0652\u062e\u064e\u0629 \u0645\u0650\u0646 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0641\u064e\u0631\u0652\u0639\u060c \u0648\u0643\u064e\u0645\u0627\u0646 \u0627\u0644\u0644\u064a \u0632\u064e\u0645\u0627\u064a\u0652\u0644\u064e\u0643 \u062c\u064e\u0631\u064e\u062f\u0648\u0647.","\u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629. \u0645\u0650\u0646 \u0647\u0650\u0646\u0627 \u0628\u0650\u062a\u064f\u0648\u0635\u064e\u0644 \u0644\u0650\u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u062a\u0627\u0646\u0652\u064a\u064e\u0629: \u0627\u0644\u0628\u0627\u0642\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0648\u0645\u064e\u0646\u0652\u0637\u0650\u0642\u0650\u0629 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0642\u0627\u0631\u064a\u0631\u060c \u0648\u0627\u0644\u0639\u064e\u062c\u0652\u0632\u060c \u0648\u0627\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0642\u0652\u0631\u064a\u0631 \u0627\u0644\u0645\u064f\u062c\u064e\u0645\u064e\u0651\u0639\u060c \u0648\u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0644\u064a \u0645\u0627 \u0627\u062a\u0652\u062d\u064e\u0641\u064e\u0638\u0650\u062a\u0652\u0634\u060c \u0648\u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a.","\u0637\u064e\u0644\u064e\u0628 \u0627\u0644\u062c\u064e\u0631\u0652\u062f. \u0627\u0644\u0643\u0627\u0631\u0652\u062a \u062f\u064e\u0647 \u0628\u0650\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0644\u064e\u0645\u0651\u0627 \u064a\u0650\u0643\u0648\u0646 \u0641\u0650\u064a\u0647 \u062c\u064e\u0631\u0652\u062f \u0645\u0650\u062a\u064e\u0651\u0641\u0650\u0642 \u0639\u064e\u0644\u0650\u064a\u0647 \u0645\u064e\u0639\u064e \u0627\u0644\u062f\u064e\u0651\u0639\u0652\u0645. \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u062a\u0650\u0628\u0652\u062f\u064e\u0623\u0648\u0627\u060c \u062f\u064f\u0648\u0633 \u0647\u064e\u0646\u0650\u0628\u0652\u062f\u064e\u0623 \u0627\u0644\u062c\u064e\u0631\u0652\u062f. \u0648\u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u062e\u0652\u0644\u064e\u0635\u0648\u0627\u060c \u062f\u064f\u0648\u0633 \u062e\u0650\u0644\u0650\u0635\u0652\u0646\u0627 \u0627\u0644\u062c\u064e\u0631\u0652\u062f.","\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0645\u0627 \u0627\u062a\u0652\u062d\u064e\u0641\u064e\u0638\u0650\u062a\u0652\u0634. \u0644\u064e\u0648\u0652 \u0635\u0650\u0646\u0652\u0641 \u0627\u0644\u0633\u0650\u0651\u064a\u0631\u0652\u0641\u064e\u0631 \u0631\u064e\u0641\u064e\u0636\u064f\u0647\u060c \u0623\u064e\u0648\u0652 \u0645\u0627 \u0631\u064e\u062f\u0650\u0651\u0634 \u0639\u064e\u0644\u0650\u064a\u0647\u060c \u0628\u0650\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0647\u0650\u0646\u0627 \u0628\u0650\u0627\u0644\u0623\u064e\u062d\u0652\u0645\u064e\u0631. \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0650\u064a\u0647 \u062a\u0652\u0634\u0648\u0641\u0652\u0647\u064f\u0645\u060c \u0648\u0627\u0628\u0652\u0639\u064e\u062a\u0652\u0647\u064f\u0645 \u062a\u0627\u0646\u064a \u0628\u0650\u062f\u0648\u0633\u064e\u0629 \u0648\u0627\u062d\u0652\u062f\u064e\u0629.","\u0646\u0650\u0633\u0652\u0628\u0650\u0629 \u0627\u0644\u062c\u064e\u0631\u0652\u062f. \u0627\u0644\u0634\u064e\u0651\u0631\u064a\u0637 \u062f\u064e\u0647 \u0628\u0650\u064a\u0652\u0648\u064e\u0631\u0651\u064a\u0643 \u062c\u064e\u0631\u064e\u062f\u0652\u062a\u0648\u0627 \u0643\u0627\u0645 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0646 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0645\u064e\u062d\u064e\u0644\u0651 \u0643\u064f\u0644\u064f\u0651\u0647\u060c \u0648\u0627\u0644\u0646\u0650\u0651\u0633\u0652\u0628\u064e\u0629 \u0643\u0627\u0645 \u0641\u064a \u0627\u0644\u0645\u0650\u064a\u064e\u0651\u0629.","\u0627\u0644\u062a\u064e\u0651\u0639\u0652\u0644\u064a\u0645\u0627\u062a. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u062a\u0650\u0641\u0652\u062a\u064e\u062d \u062a\u064e\u0639\u0652\u0644\u064a\u0645\u0627\u062a \u0627\u0644\u062c\u064e\u0631\u0652\u062f \u0628\u0650\u062a\u0627\u0639\u0650\u0629 \u0627\u0644\u0641\u064e\u0631\u0652\u0639 \u062f\u064e\u0647. \u0627\u0642\u0652\u0631\u0627\u0647\u0627 \u0643\u064f\u0648\u064e\u064a\u0650\u0651\u0633 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u064e\u0631\u064e\u0651\u0629.","\u0639\u064e\u062f\u0651\u0627\u062f \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0644\u064a \u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639. \u0627\u0644\u0645\u064f\u0631\u064e\u0628\u064e\u0651\u0639 \u0627\u0644\u0628\u064f\u0631\u0652\u062a\u064f\u0642\u0627\u0646\u064a \u062f\u064e\u0647 \u0628\u0650\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0637\u0648\u0644 \u0645\u0627 \u0641\u0650\u064a\u0647 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0644\u0650\u0633\u064e\u0651\u0647 \u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639\u060c \u0648\u0627\u0644\u0631\u064e\u0651\u0642\u064e\u0645 \u0627\u0644\u0644\u064a \u0641\u0650\u064a\u0647 \u0647\u064f\u0648\u064e\u0651 \u0639\u064e\u062f\u064e\u062f\u0652\u0647\u064f\u0645. \u0648\u0628\u0650\u064a\u0650\u062e\u0652\u062a\u0650\u0641\u064a \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u0643\u064f\u0644\u064f\u0651\u0647 \u064a\u064f\u0648\u0635\u064e\u0644.","\u0627\u0644\u0639\u064e\u0644\u0627\u0645\u064e\u0629 \u0627\u0644\u0643\u0650\u0628\u064a\u0631\u064e\u0629 \u0641\u064f\u0648\u0642. \u0644\u064e\u0648\u0652 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u0642\u0650\u0637\u0650\u0639 \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u062f\u0650\u0642\u064a\u0642\u064e\u0629\u060c \u0647\u064e\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u0634\u064e\u0631\u064a\u0637 \u0643\u0650\u0628\u064a\u0631 \u0641\u064f\u0648\u0642 \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u0641\u0650\u064a\u0647 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641. \u0645\u064e\u0639\u0652\u0646\u0627\u0647: \u0645\u0627 \u062a\u0650\u0642\u0652\u0641\u0650\u0644\u0652\u0634 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639. \u0648\u0644\u064e\u0645\u0651\u0627 \u0643\u064f\u0644\u064f\u0651\u0647 \u064a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639\u060c \u0647\u064e\u064a\u0652\u0642\u0652\u0644\u0650\u0628 \u0623\u064e\u062e\u0652\u0636\u064e\u0631 \u0648\u064a\u0650\u062e\u0652\u062a\u0650\u0641\u064a.","\u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u0645\u0650\u0634 \u0647\u064e\u062a\u0650\u0646\u0652\u0637\u0650\u0641\u064a\u060c \u0637\u0648\u0644 \u0645\u0627 \u0641\u0650\u064a\u0647 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0644\u0650\u0633\u064e\u0651\u0647 \u0639\u064e\u0644\u0649 \u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644\u064e\u0643\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u0627\u0644\u0631\u064e\u0651\u0641\u0652\u0639 \u0645\u0627 \u064a\u0650\u0642\u064e\u0641\u0650\u0651\u0634. \u0645\u0627 \u062a\u0650\u0642\u0652\u0641\u0650\u0644\u0652\u0634 \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629\u060c \u0648\u0645\u0627 \u062a\u0650\u0642\u0652\u0641\u0650\u0644\u0652\u0634 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642\u060c \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u0632\u064f\u0631\u0627\u0631 \u062e\u0650\u0644\u0650\u0635\u0652\u062a \u064a\u0650\u062e\u0652\u0636\u064e\u0631\u0651.","\u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f. \u0644\u064e\u0648\u0652 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0645\u0650\u0634 \u0642\u0627\u062f\u0652\u0631\u064e\u0629 \u062a\u0650\u0642\u0652\u0631\u0627 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f\u060c \u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0628\u0650\u0625\u0650\u064a\u062f\u064e\u0643 \u0647\u0650\u0646\u0627\u060c \u0648\u062f\u064f\u0648\u0633 \u0627\u0644\u0633\u064e\u0651\u0647\u0652\u0645.","\u062f\u064e\u0648\u064e\u0651\u0631 \u0628\u0650\u0627\u0644\u0627\u0633\u0652\u0645. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0645\u0627\u0644\u0648\u0634 \u0628\u0627\u0631\u0643\u0648\u062f\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u0643\u0652\u062a\u0650\u0628 \u062c\u064f\u0632\u0652\u0621 \u0645\u0650\u0646 \u0627\u0633\u0652\u0645\u064f\u0647\u060c \u0623\u064e\u0648\u0652 \u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f\u060c \u0648\u0627\u062e\u0652\u062a\u0627\u0631\u064f\u0647 \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629.","\u0632\u064f\u0631\u0627\u0631 \u0627\u0644\u0645\u064e\u0633\u0652\u062d \u0627\u0644\u0643\u0650\u0628\u064a\u0631. \u062f\u064e\u0647 \u0627\u0644\u0644\u064a \u0647\u064e\u062a\u0650\u0633\u0652\u062a\u064e\u062e\u0652\u062f\u0650\u0645\u064f\u0647 \u0623\u064e\u063a\u0652\u0644\u064e\u0628 \u0627\u0644\u0648\u064e\u0642\u0652\u062a. \u062f\u064f\u0648\u0633 \u0641\u064a \u0623\u064e\u064a\u0651 \u062d\u0650\u062a\u064e\u0651\u0629 \u0641\u064a \u0627\u0644\u0645\u064f\u0631\u064e\u0628\u064e\u0651\u0639 \u062f\u064e\u0647\u060c \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0647\u064e\u062a\u0650\u0641\u0652\u062a\u064e\u062d. \u0648\u064e\u062c\u0650\u0651\u0647 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0639\u064e\u0644\u0649 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f\u060c \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u062a\u0650\u0633\u0652\u0645\u064e\u0639 \u062a\u064a\u062a\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u064a\u0650\u0642\u0648\u0644 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641. \u0647\u064e\u062a\u0650\u0641\u0652\u062a\u064e\u062d \u0634\u0627\u0634\u0650\u0629 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641\u060c \u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0639\u064e\u062f\u064e\u062f\u060c \u0648\u062f\u064f\u0648\u0633 \u062d\u0650\u0641\u0652\u0638 \u0627\u0644\u062a\u064e\u0651\u0627\u0644\u064a.","\u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u062e\u0652\u0644\u064e\u0635. \u0627\u0633\u0652\u062a\u064e\u0646\u0651\u0649 \u0644\u0650\u062d\u064e\u062f\u0651 \u0645\u0627 \u0627\u0644\u0639\u064e\u062f\u0651\u0627\u062f \u064a\u0650\u062e\u0652\u0644\u064e\u0635\u060c \u0648\u0632\u064f\u0631\u0627\u0631 \u062e\u0650\u0644\u0650\u0635\u0652\u062a \u0641\u064f\u0648\u0642 \u064a\u0650\u062e\u0652\u0636\u064e\u0631\u0651. \u062f\u064f\u0648\u0633 \u062e\u0650\u0644\u0650\u0635\u0652\u062a. \u0648\u0628\u064e\u0639\u0652\u062f\u064e\u0647\u0627 \u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0650\u0639\u0652\u0645\u0650\u0644 \u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u062e\u064f\u0631\u0648\u062c\u060c \u0623\u064e\u0648\u0652 \u062a\u0650\u0642\u0652\u0641\u0650\u0644 \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642.","\u0623\u064e\u0647\u0652\u0644\u064b\u0627 \u0628\u0650\u064a\u0643 \u0641\u064a \u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645 \u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631. \u0645\u0650\u0646 \u0647\u0650\u0646\u0627 \u0628\u0650\u062a\u0650\u0633\u0652\u062a\u0650\u0644\u0650\u0645 \u0627\u0644\u0628\u0650\u0636\u0627\u0639\u064e\u0629 \u0627\u0644\u0644\u064a \u062c\u0627\u064a\u064e\u0651\u0629 \u0645\u0650\u0646 \u0627\u0644\u0645\u064e\u062e\u0652\u0632\u064e\u0646 \u0627\u0644\u0631\u064e\u0651\u0626\u064a\u0633\u064a\u060c \u0635\u0650\u0646\u0652\u0641 \u0635\u0650\u0646\u0652\u0641\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0628\u0650\u064a\u0652\u0637\u064e\u0644\u064e\u0651\u0639\u0652\u0644\u064e\u0643 \u0627\u0644\u0646\u064e\u0651\u0627\u0642\u0650\u0635 \u0648\u0627\u0644\u0632\u0650\u0651\u064a\u0627\u062f\u064e\u0629.","\u0627\u0644\u0641\u064e\u0648\u0627\u062a\u064a\u0631 \u0627\u0644\u0644\u064a \u062c\u0627\u064a\u064e\u0651\u0629. \u0643\u064f\u0644\u0651 \u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0637\u0627\u0644\u0652\u0639\u064e\u0629 \u0644\u0650\u0644\u0641\u064e\u0631\u0652\u0639 \u0628\u0650\u062a\u0650\u0638\u0652\u0647\u064e\u0631 \u0647\u0650\u0646\u0627\u060c \u0648\u062a\u064e\u062d\u0652\u062a\u064e\u0647\u0627 \u0627\u062a\u0652\u0633\u064e\u0644\u0650\u0651\u0645 \u0645\u0650\u0646\u0652\u0647\u0627 \u0643\u0627\u0645 \u0635\u0650\u0646\u0652\u0641. \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0649 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0650\u0628\u0652\u062f\u064e\u0623 \u062a\u0650\u0633\u0652\u062a\u0650\u0644\u0650\u0645. \u0648\u0627\u0633\u0652\u062d\u064e\u0628 \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629 \u0644\u0650\u062a\u064e\u062d\u0652\u062a\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0652\u062d\u064e\u062f\u0650\u0651\u062b \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629.","\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0645\u0650\u0646 \u0627\u0644\u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c. \u0628\u0650\u064a\u0652\u062c\u064a\u0628 \u0641\u0627\u062a\u0648\u0631\u0650\u0629 \u0627\u0644\u062a\u064e\u0651\u062d\u0652\u0648\u064a\u0644 \u0645\u0650\u0646 \u0628\u064e\u0631\u0652\u0646\u0627\u0645\u0650\u062c \u0627\u0644\u0628\u0650\u064a\u0639 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644\u060c \u0648\u062a\u0650\u0628\u0652\u062f\u064e\u0623 \u062a\u0650\u0633\u0652\u062a\u0650\u0644\u0650\u0645\u0652\u0647\u0627.","\u0631\u064e\u0641\u0652\u0639 \u0645\u0650\u0644\u064e\u0641\u0651 \u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645. \u0644\u064e\u0648\u0652 \u0645\u064e\u0639\u0627\u0643 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0645\u0650\u0644\u064e\u0641\u0651 \u0625\u0650\u0643\u0652\u0633\u0650\u0644\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627 \u0648\u0627\u062e\u0652\u062a\u0627\u0631 \u0627\u0644\u0645\u0650\u0644\u064e\u0641\u0651\u060c \u0648\u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u062a\u0650\u062a\u0652\u062d\u064e\u0645\u0650\u0651\u0644 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064e\u0647\u0627.","\u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629. \u0641\u064a\u0647\u0627: \u062d\u064e\u062c\u0652\u0645 \u0627\u0644\u0639\u064e\u0631\u0652\u0636\u060c \u0648\u062a\u064e\u062d\u0652\u062f\u064a\u062b \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u0648\u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u0627\u0644\u062e\u064f\u0631\u0648\u062c\u060c \u0648\u0625\u0650\u0639\u0627\u062f\u0650\u0629 \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647.","\u0634\u0627\u0634\u0650\u0629 \u0627\u0644\u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645. \u0647\u0650\u0646\u0627 \u0628\u0650\u062a\u0650\u0633\u0652\u062a\u0650\u0644\u0650\u0645 \u0623\u064e\u0635\u0652\u0646\u0627\u0641 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u062f\u064a \u0648\u0627\u062d\u0650\u062f \u0648\u0627\u062d\u0650\u062f. \u0647\u064e\u0646\u0652\u0639\u064e\u062f\u0650\u0651\u064a \u0639\u064e\u0644\u0649 \u0643\u064f\u0644\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u064a \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629.","\u0627\u0644\u062a\u064e\u0651\u0627\u0628\u0627\u062a. \u0627\u0644\u0645\u0650\u062a\u0652\u0628\u064e\u0642\u0651\u064a: \u0627\u0644\u0644\u064a \u0644\u0650\u0633\u064e\u0651\u0647 \u0645\u0627 \u0627\u062a\u0652\u0633\u064e\u0644\u0650\u0651\u0645\u0652\u0634. \u0646\u0627\u0642\u0650\u0635: \u0648\u0650\u0635\u0650\u0644 \u0645\u0650\u0646\u064f\u0651\u0647 \u0623\u064e\u0642\u064e\u0644\u0651 \u0645\u0650\u0646 \u0627\u0644\u0645\u064e\u0637\u0652\u0644\u0648\u0628. \u0632\u0650\u064a\u0627\u062f\u064e\u0629: \u0648\u0650\u0635\u0650\u0644 \u0623\u064e\u0643\u0652\u062a\u064e\u0631\u060c \u0623\u064e\u0648\u0652 \u0645\u0650\u0634 \u0641\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629 \u0623\u064e\u0635\u0652\u0644\u064b\u0627. \u0648\u0627\u062a\u0652\u0633\u064e\u0644\u0650\u0651\u0645: \u0627\u0644\u0644\u064a \u062e\u0650\u0644\u0650\u0635\u060c \u0648\u0645\u064a\u0646 \u0627\u0644\u0644\u064a \u0627\u0633\u0652\u062a\u064e\u0644\u064e\u0645\u064f\u0647.","\u0627\u0644\u0639\u064e\u062f\u0651\u0627\u062f. \u0627\u062a\u0652\u0633\u064e\u0644\u0650\u0651\u0645 \u0643\u0627\u0645 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0646 \u0643\u0627\u0645\u060c \u0648\u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0642\u0650\u0637\u064e\u0639 \u0627\u0644\u0644\u064a \u0648\u0650\u0635\u0652\u0644\u0650\u062a \u0645\u0650\u0646 \u0627\u0644\u0645\u064e\u0637\u0652\u0644\u0648\u0628\u060c \u0648\u0627\u0644\u0646\u064e\u0651\u0627\u0642\u0650\u0635 \u0623\u064e\u0648\u0652 \u0627\u0644\u0632\u0650\u0651\u064a\u0627\u062f\u064e\u0629.","\u062f\u064e\u0648\u064e\u0651\u0631\u060c \u0623\u064e\u0648\u0652 \u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f. \u0627\u0643\u0652\u062a\u0650\u0628 \u062c\u064f\u0632\u0652\u0621 \u0645\u0650\u0646 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u062a\u0652\u062f\u064e\u0648\u064e\u0651\u0631 \u0639\u064e\u0644\u0650\u064a\u0647\u060c \u0623\u064e\u0648\u0652 \u0627\u0643\u0652\u062a\u0650\u0628 \u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f\u060c \u0648\u062f\u064f\u0648\u0633 \u0628\u064e\u062d\u0652\u062b.","\u0627\u0639\u0652\u0645\u0650\u0644 \u0633\u0652\u0643\u0627\u0646. \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u0645\u0652\u0633\u064e\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0641\u064a \u0625\u0650\u064a\u062f\u064e\u0643\u060c \u0648\u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0643\u0650\u0645\u0650\u0651\u064a\u064e\u0651\u0629 \u0627\u0644\u0644\u064a \u0648\u0650\u0635\u0652\u0644\u0650\u062a. \u0644\u064e\u0648\u0652 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0622\u062e\u0652\u0631\u064f\u0647 \u0646\u0650\u062c\u0652\u0645\u064e\u0629 \u0648\u0631\u064e\u0642\u064e\u0645\u060c \u0647\u064e\u062a\u0652\u0644\u0627\u0642\u064a \u062e\u0627\u0646\u064e\u0629 \u0644\u0650\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0648\u062e\u0627\u0646\u064e\u0629 \u0644\u0650\u0644\u0641\u064e\u0631\u0652\u0637\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u064a\u0650\u062d\u0652\u0633\u0650\u0628 \u0627\u0644\u0642\u0650\u0637\u064e\u0639 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647. \u0648\u0644\u064e\u0648\u0652 \u062c\u0627\u0644\u064e\u0643 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0634 \u0641\u064a \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u064e\u0629\u060c \u0627\u0645\u0652\u0633\u064e\u062d\u064f\u0647 \u0639\u0627\u062f\u064a\u060c \u0648\u064a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0632\u0650\u064a\u0627\u062f\u064e\u0629.","\u062e\u0650\u0644\u0650\u0635\u0652\u062a. \u0644\u064e\u0645\u0651\u0627 \u062a\u0650\u062e\u064e\u0644\u064e\u0651\u0635 \u0643\u064f\u0644\u0651 \u0627\u0644\u0623\u064e\u0635\u0652\u0646\u0627\u0641\u060c \u062f\u064f\u0648\u0633 \u0647\u0650\u0646\u0627\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u064a\u0650\u0642\u0648\u0644\u064e\u0651\u0643 \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u062d\u0627\u062c\u064e\u0629 \u0646\u0627\u0642\u0652\u0635\u064e\u0629\u060c \u0642\u064e\u0628\u0652\u0644 \u0645\u0627 \u064a\u0650\u0642\u0652\u0641\u0650\u0644 \u0627\u0644\u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645.","\u0645\u064f\u0634\u0627\u0631\u0652\u0643\u0650\u0629 \u0627\u0644\u062a\u064e\u0651\u0642\u0652\u0631\u064a\u0631. \u062a\u0650\u0628\u0652\u0639\u064e\u062a \u062a\u064e\u0642\u0652\u0631\u064a\u0631 \u0627\u0644\u0627\u0633\u0652\u062a\u0650\u0644\u0627\u0645 \u0639\u064e\u0644\u0649 \u0648\u0627\u062a\u0652\u0633\u0627\u0628: \u0627\u0644\u0646\u064e\u0651\u0627\u0642\u0650\u0635\u060c \u0648\u0627\u0644\u0632\u0650\u0651\u064a\u0627\u062f\u064e\u0629\u060c \u0648\u0645\u064a\u0646 \u0627\u0633\u0652\u062a\u064e\u0644\u064e\u0645 \u0625\u0650\u064a\u0647.","\u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a. \u062d\u064e\u062c\u0652\u0645 \u0627\u0644\u0639\u064e\u0631\u0652\u0636\u060c \u0648\u062a\u064e\u0633\u0652\u062c\u064a\u0644 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0643\u0650\u0645\u0650\u0651\u064a\u062a\u064f\u0647 \u0648\u0627\u062d\u0650\u062f \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647\u060c \u0648\u0625\u0650\u0639\u0627\u062f\u0650\u0629 \u0627\u0644\u0634\u064e\u0651\u0631\u0652\u062d \u062f\u064e\u0647.","\u0645\u064e\u0641\u064a\u0634 \u0646\u0650\u062a\u0651\u061f \u0648\u064e\u0644\u0627 \u064a\u0652\u0647\u0650\u0645\u064e\u0651\u0643. \u0643\u064f\u0644\u0651 \u0635\u0650\u0646\u0652\u0641 \u0628\u0650\u062a\u0650\u0633\u0652\u062a\u0650\u0644\u0652\u0645\u064f\u0647 \u0628\u0650\u064a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u0627\u0644\u0623\u064e\u0648\u0650\u0651\u0644\u060c \u0648\u0628\u0650\u064a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u064a\u0650\u0631\u0652\u062c\u064e\u0639. \u0648\u0627\u0644\u0639\u064e\u0644\u0627\u0645\u064e\u0629 \u0627\u0644\u0635\u064e\u0651\u0641\u0652\u0631\u0627 \u0627\u0644\u0644\u064a \u0641\u064f\u0648\u0642\u060c \u0628\u0650\u062a\u0652\u0642\u0648\u0644\u064e\u0651\u0643 \u0641\u0650\u064a\u0647 \u0643\u0627\u0645 \u0635\u0650\u0646\u0652\u0641 \u0645\u0650\u0633\u0652\u062a\u064e\u0646\u0651\u064a \u0627\u0644\u0646\u0650\u0651\u062a\u0651.","\u0623\u064e\u0647\u0652\u0644\u064b\u0627 \u0628\u0650\u064a\u0643 \u0641\u064a \u062c\u064e\u0631\u0652\u062f \u0645\u064f\u062f\u064e\u0642\u0650\u0651\u0642. \u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u062f\u064e\u0647 \u0628\u0650\u064a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0627\u0644\u062c\u064e\u0631\u0652\u062f \u0639\u064e\u0644\u0649 \u0634\u064a\u062a \u0627\u0644\u0645\u064e\u062d\u064e\u0644\u0651 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644\u060c \u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0648\u064e\u0631\u064e\u0642\u060c \u0648\u0645\u0650\u0646 \u063a\u0650\u064a\u0631 \u0627\u0633\u0652\u062a\u0650\u0646\u0651\u0649. \u062e\u064e\u0644\u0651\u064a\u0646\u0627 \u0646\u0650\u0644\u0650\u0641\u0651 \u0644\u064e\u0641\u064e\u0651\u0629 \u0633\u064e\u0631\u064a\u0639\u064e\u0629 \u0639\u064e\u0644\u0649 \u0623\u064e\u0647\u064e\u0645\u0651 \u062d\u0627\u062c\u064e\u0629 \u0641\u0650\u064a\u0647.","\u0627\u0645\u0652\u0633\u064e\u062d \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f. \u062f\u064f\u0648\u0633 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0631\u064e\u0628\u064e\u0651\u0639 \u0627\u0644\u0623\u064e\u0632\u0652\u0631\u064e\u0642 \u0627\u0644\u0643\u0650\u0628\u064a\u0631 \u062a\u064e\u062d\u0652\u062a\u060c \u0648\u0648\u064e\u062c\u0650\u0651\u0647 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0639\u064e\u0644\u0649 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f. \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u064a\u0650\u0642\u0652\u0631\u0627\u0647\u060c \u0647\u064e\u062a\u0650\u0633\u0652\u0645\u064e\u0639 \u062a\u064a\u062a. \u0648\u0628\u0627\u0631\u0643\u0648\u062f \u0627\u0644\u0645\u064a\u0632\u0627\u0646\u060c \u0628\u0650\u064a\u0650\u062a\u0652\u0639\u0650\u0631\u0650\u0641 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647\u060c \u0648\u0627\u0644\u0648\u064e\u0632\u0652\u0646 \u0628\u0650\u064a\u0650\u062a\u0652\u0643\u0650\u062a\u0650\u0628 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647.","\u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u0628\u0650\u064a\u0652\u0646\u064e\u0628\u0650\u0651\u0647\u064e\u0643. \u0628\u0650\u064a\u0652\u0642\u0648\u0644 \u0627\u0633\u0652\u0645 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0628\u0650\u0635\u064f\u0648\u062a \u0639\u0627\u0644\u064a\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u062a\u0650\u062a\u0652\u0623\u064e\u0643\u0650\u0651\u062f \u0625\u0650\u0646\u064f\u0651\u0647 \u0647\u064f\u0648\u064e\u0651. \u0648\u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0645\u0650\u0634\u064e\u0643\u0650\u0651\u0644\u060c \u0647\u064e\u062a\u0650\u0633\u0652\u0645\u064e\u0639 \u0646\u064e\u063a\u0652\u0645\u064e\u0629 \u0645\u064f\u062e\u0652\u062a\u064e\u0644\u0650\u0641\u064e\u0629\u060c \u0648\u064a\u0650\u0638\u0652\u0647\u064e\u0631 \u062a\u064e\u0646\u0652\u0628\u064a\u0647 \u0628\u064f\u0631\u0652\u062a\u064f\u0642\u0627\u0646\u064a: \u0639\u0650\u062f\u0651 \u0643\u064f\u0644\u0651 \u0627\u0644\u0623\u064e\u0644\u0652\u0648\u0627\u0646 \u0645\u064e\u0639\u064e \u0628\u064e\u0639\u0652\u0636.","\u0627\u0643\u0652\u062a\u0650\u0628 \u0627\u0644\u0639\u064e\u062f\u064e\u062f\u060c \u0648\u062f\u064f\u0648\u0633 \u062d\u0650\u0641\u0652\u0638. \u0647\u064e\u064a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638\u060c \u0648\u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u062a\u0650\u0641\u0652\u062a\u064e\u062d \u062a\u0627\u0646\u064a \u0644\u0650\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0627\u0644\u0644\u064a \u0628\u064e\u0639\u0652\u062f\u064f\u0647. \u0644\u064e\u0648\u0652 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0628\u0650\u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0627\u0643\u0652\u062a\u0650\u0628 \u0639\u064e\u062f\u064e\u062f \u0627\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0648\u0628\u064e\u0639\u0652\u062f\u064a\u0646 \u0627\u0644\u0642\u0650\u0637\u064e\u0639 \u0627\u0644\u0641\u064e\u0631\u0652\u062f\u064a.","\u0644\u064f\u0648\u062d\u0650\u0629 \u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0643\u0650\u0628\u064a\u0631\u064e\u0629. \u0632\u064e\u0631\u0627\u064a\u0631 \u0627\u0644\u0623\u064e\u0631\u0652\u0642\u0627\u0645 \u0643\u0650\u0628\u064a\u0631\u064e\u0629 \u062a\u064e\u062d\u0652\u062a \u0627\u0644\u0634\u064e\u0651\u0627\u0634\u064e\u0629\u060c \u0648\u0641\u064a\u0647\u0627 \u0636\u064e\u0631\u0652\u0628 \u0648\u062c\u064e\u0645\u0652\u0639. \u0627\u0643\u0652\u062a\u0650\u0628 \u062a\u064e\u0644\u0627\u062a\u064e\u0629 \u0641\u064a \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u064e\u0629\u060c \u0648\u0647\u0650\u064a\u064e\u0651 \u062a\u0650\u062d\u0652\u0633\u0650\u0628 \u0627\u062a\u0652\u0646\u0627\u0634\u064e\u0631 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064e\u0647\u0627.","\u0646\u064e\u0641\u0652\u0633 \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641 \u0641\u064a \u0623\u064e\u0643\u0652\u062a\u064e\u0631 \u0645\u0650\u0646 \u0645\u064e\u0643\u0627\u0646. \u0643\u064f\u0644\u0651 \u0645\u064e\u0631\u064e\u0651\u0629 \u062a\u0650\u062c\u0652\u0631\u064f\u062f \u0627\u0644\u0635\u0650\u0651\u0646\u0652\u0641\u060c \u0628\u0650\u064a\u0650\u062a\u0652\u0633\u064e\u062c\u0650\u0651\u0644 \u0641\u064a \u062e\u0627\u0646\u064e\u0629 \u062c\u0650\u062f\u064a\u062f\u064e\u0629\u060c \u0648\u0627\u0644\u062a\u064e\u0651\u0637\u0652\u0628\u064a\u0642 \u0628\u0650\u064a\u0650\u062c\u0652\u0645\u064e\u0639\u0652\u0647\u064f\u0645 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064f\u0647. \u0648\u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u0631\u064e\u0642\u064e\u0645 \u063a\u064e\u0644\u064e\u0637\u060c \u062f\u064f\u0648\u0633 \u0641\u064e\u062a\u0652\u062d \u0627\u0644\u062a\u064e\u0651\u0639\u0652\u062f\u064a\u0644\u060c \u0648\u0635\u064e\u0644\u064e\u0651\u062d\u064f\u0647.","\u0635\u0648\u0631\u064e\u0629 \u0644\u0650\u0643\u064f\u0644\u0651 \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629. \u0635\u064e\u0648\u064e\u0651\u0631 \u0643\u064f\u0644\u0651 \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629\u060c \u0639\u064e\u0644\u064e\u0634\u0627\u0646 \u0627\u0644\u0643\u064f\u0644\u0651 \u064a\u0650\u0639\u0652\u0631\u064e\u0641 \u0647\u0650\u064a\u064e\u0651 \u0641\u064a\u0646. \u0648\u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629\u060c \u062a\u0650\u0642\u0652\u062f\u064e\u0631 \u062a\u0652\u0634\u0648\u0641 \u0635\u0648\u0631\u0650\u0629 \u0643\u064f\u0644\u0651 \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u064e\u0629.","\u0645\u064e\u0641\u064a\u0634 \u0646\u0650\u062a\u0651\u061f \u0648\u064e\u0644\u0627 \u064a\u0652\u0647\u0650\u0645\u064e\u0651\u0643. \u0627\u0644\u062c\u064e\u0631\u0652\u062f \u0628\u0650\u064a\u0650\u062a\u0652\u062d\u0650\u0641\u0650\u0638 \u0639\u064e\u0644\u0649 \u0627\u0644\u0645\u064f\u0648\u0628\u0627\u064a\u0652\u0644 \u0639\u064e\u0644\u0649 \u0637\u0648\u0644. \u0648\u0623\u064e\u064a\u0652\u0642\u0648\u0646\u0650\u0629 \u0627\u0644\u0633\u064e\u0651\u062d\u0627\u0628\u064e\u0629 \u0641\u064f\u0648\u0642\u060c \u0628\u0650\u062a\u0652\u0642\u0648\u0644\u064e\u0651\u0643 \u0644\u064e\u0648\u0652 \u0641\u0650\u064a\u0647 \u062d\u0627\u062c\u064e\u0629 \u0644\u0650\u0633\u064e\u0651\u0647 \u0645\u0627 \u0627\u062a\u0652\u0631\u064e\u0641\u064e\u0639\u0650\u062a\u0652\u0634\u060c \u0648\u0628\u0650\u062a\u0650\u062a\u0652\u0631\u0650\u0641\u0650\u0639 \u0644\u0650\u0648\u064e\u062d\u0652\u062f\u064e\u0647\u0627 \u0623\u064e\u0648\u0650\u0651\u0644 \u0645\u0627 \u0627\u0644\u0646\u0650\u0651\u062a\u0651 \u064a\u0650\u0631\u0652\u062c\u064e\u0639.","\u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629. \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u064a\u0652\u0645\u064e\u0629 \u062a\u0652\u0634\u0648\u0641: \u0627\u0644\u0628\u0627\u0642\u064a \u0639\u064e\u0644\u0649 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0648\u0627\u0644\u0639\u064e\u062c\u0652\u0632\u060c \u0648\u0627\u0644\u0643\u064e\u0631\u0627\u062a\u064a\u0646\u060c \u0648\u062a\u064e\u0642\u0652\u0631\u064a\u0631 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0648\u062a\u064e\u0642\u0652\u064a\u064a\u0645 \u0627\u0644\u0645\u064f\u0648\u064e\u0638\u064e\u0651\u0641\u064a\u0646. \u0648\u0645\u0650\u0646 \u0627\u0644\u0625\u0650\u0639\u0652\u062f\u0627\u062f\u0627\u062a\u060c \u062a\u0652\u063a\u064e\u064a\u064e\u0651\u0631 \u0645\u064e\u0646\u0652\u0637\u0650\u0642\u0650\u0629 \u0627\u0644\u062c\u064e\u0631\u0652\u062f\u060c \u0623\u064e\u0648\u0652 \u062a\u0650\u0642\u0652\u0641\u0650\u0644 \u0646\u064f\u0637\u0652\u0642 \u0627\u0644\u0623\u064e\u0633\u0627\u0645\u064a."],t.w)
